            "You call forth an Undead spirit that takes a Ghostly, Putrid, or Skeletal form of your choice. It obeys your commands and acts on your turn.",
            setOf(WARLOCK, WIZARD), concentration = true),
        SpellDef("giant_insect", "Giant Insect", 4, "Transmutation", "Action", "30 feet", "V, S", "10 minutes",
            "You summon a giant insect, which uses the Giant Insect stat block and obeys your commands. It grows more capable when cast with a higher-level slot.",
            setOf(CLERIC, DRUID, SORCERER), concentration = true),
        SpellDef("phantasmal_killer", "Phantasmal Killer", 4, "Illusion", "Action", "120 feet", "V, S", "1 minute",
            "You tap into a creature's nightmares. It makes a Wisdom saving throw, taking 4d10 Psychic damage on a failure and having Disadvantage on saves against the spell while it is Frightened of the illusion.",
            setOf(WARLOCK, WIZARD), concentration = true),
        SpellDef("hallucinatory_terrain", "Hallucinatory Terrain", 4, "Illusion", "10 minutes", "300 feet", "V, S, M", "24 hours",
            "You make natural terrain in a 150-foot cube look, sound, and smell like other natural terrain. Physical contact with the illusion reveals it.",
            setOf(BARD, DRUID, WARLOCK, WIZARD)),
        SpellDef("dispel_evil_and_good", "Dispel Evil and Good", 5, "Abjuration", "Action", "Self", "V, S, M", "1 minute",
            "Celestials, Elementals, Fey, Fiends, and Undead have Disadvantage on attack rolls against you, and you can use a Magic action to attempt to break an enchantment or dismiss such a creature back to its home plane.",
            setOf(CLERIC, PALADIN), concentration = true),
        SpellDef("antilife_shell", "Antilife Shell", 5, "Abjuration", "Action", "Self (10-foot radius)", "V, S", "1 hour",
            "A shimmering barrier in a 10-foot Emanation prevents creatures other than Constructs and Undead from passing through it, though they can cast spells and make attacks with reach through it.",
            setOf(DRUID), concentration = true),
        SpellDef("contagion", "Contagion", 5, "Necromancy", "Action", "Touch", "V, S", "7 days",
            "Your touch inflicts a magical contagion. The target makes a Constitution saving throw, taking 11d8 Necrotic damage on a failure and having the Poisoned condition until the spell ends.",
            setOf(CLERIC, DRUID), ),
        SpellDef("insect_plague", "Insect Plague", 5, "Conjuration", "Action", "300 feet", "V, S, M", "10 minutes",
            "A swarm of biting locusts fills a 20-foot-radius Sphere. The area is Lightly Obscured and Difficult Terrain, and each creature there takes 4d10 Piercing damage on a failed Constitution save.",
            setOf(CLERIC, DRUID, SORCERER), concentration = true),
        SpellDef("destructive_wave", "Destructive Wave", 5, "Evocation", "Action", "Self (30-foot radius)", "V", "Instantaneous",
            "Divine energy ripples out from you. Each creature of your choice in a 30-foot Emanation makes a Constitution saving throw, taking 5d6 Thunder damage plus 5d6 Radiant or Necrotic damage (your choice) and having the Prone condition on a failure.",
            setOf(CLERIC, PALADIN, DRUID)),
        SpellDef("creation", "Creation", 5, "Illusion", "1 minute", "30 feet", "V, S, M", "Special",
            "You pull wisps of shadow material from the Shadowfell to create a nonliving object of vegetable matter or mineral, up to a 5-foot Cube. It lasts a duration determined by its material.",
            setOf(SORCERER, WIZARD, ARTIFICER)),
        SpellDef("awaken", "Awaken", 5, "Transmutation", "8 hours", "Touch", "V, S, M", "Instantaneous",
            "You touch a Beast or Plant with an Intelligence of 3 or less. It gains an Intelligence of 10, the ability to speak one language you know, and is Charmed by you for 30 days.",
            setOf(BARD, DRUID)),
        SpellDef("augury", "Augury", 2, "Divination", "1 minute", "Self", "V, S, M", "Instantaneous",
            "You receive an omen about the results of a course of action you plan to take within the next 30 minutes: Weal, Woe, Weal and Woe, or Nothing.",
            setOf(CLERIC, WIZARD), ritual = true),
        SpellDef("hail_of_thorns", "Hail of Thorns", 1, "Conjuration", "Bonus Action", "Self", "V", "Instantaneous",
            "Cast immediately after hitting a creature with a Ranged weapon. Thorns burst out in a 5-foot Emanation around the target; each creature there makes a Dexterity saving throw, taking 1d10 Piercing damage on a failure or half as much on a success.",
            setOf(RANGER)),
        // Above the catalogued range, but the Primordial Patron's Primordial Herald casts it
        // outright — and a grant naming a spell the catalog lacks resolves to nothing at all.
        SpellDef("planar_ally", "Planar Ally", 6, "Conjuration", "10 minutes", "60 feet", "V, S", "Instantaneous",
            "You beseech an otherworldly entity for aid, and a creature of its choice appears. You must bargain with it for service, and it departs if you fail to agree terms or it is reduced to 0 Hit Points.",
            setOf(CLERIC)),
        // ------------------------------------- Filling gaps found in the class-list sweep
        // Every one of these is a 2024 Player's Handbook spell that belonged on a class list
        // the catalog was quietly short of. A missing spell never announces itself: the
        // picker simply has one fewer row, and only the player who went looking for it knows.

        // ---- Level 1
        SpellDef("color_spray", "Color Spray", 1, "Illusion", "Action", "Self (15-foot Cone)", "V, S, M", "1 round",
            "You launch a dazzling array of flashing lights. Each creature in the Cone has the Blinded condition until the end of your next turn.",
            setOf(SORCERER, WIZARD)),
        SpellDef("compelled_duel", "Compelled Duel", 1, "Enchantment", "Bonus Action", "30 feet", "V", "1 minute",
            "You attempt to compel a creature into a duel. It makes a Wisdom saving throw; on a failure it has Disadvantage on attack rolls against creatures other than you, and it can't willingly move more than 30 feet away from you.",
            setOf(PALADIN), saveAbility = Ability.WIS, concentration = true),
        SpellDef("searing_smite", "Searing Smite", 1, "Transmutation", "Bonus Action", "Self", "V", "1 minute",
            "The next time you hit with a Melee weapon, the target takes an extra 1d6 Fire damage and begins burning, taking 1d6 Fire damage at the start of each of its turns until it or another creature takes an action to put out the flames.",
            setOf(PALADIN), damage = "1d6", damageType = "Fire", concentration = true),
        SpellDef("tensers_floating_disk", "Tenser's Floating Disk", 1, "Conjuration", "Action or Ritual", "30 feet", "V, S, M", "1 hour",
            "A circular horizontal plane of force appears, hovering 3 feet above the ground. It can hold up to 500 pounds and follows you, remaining 20 feet away or less.",
            setOf(WIZARD), ritual = true),
        SpellDef("illusory_script", "Illusory Script", 1, "Illusion", "1 minute or Ritual", "Touch", "S, M", "10 days",
            "You write on parchment and imbue it with an illusion. Only creatures you designate can read the true message; to everyone else it appears as unintelligible or entirely different writing.",
            setOf(BARD, WARLOCK, WIZARD), ritual = true),

        // ---- Level 2
        SpellDef("barkskin", "Barkskin", 2, "Transmutation", "Bonus Action", "Touch", "V, S, M", "1 hour",
            "A willing creature you touch has its skin take on a bark-like appearance, and it has an Armor Class of 17 if its AC is lower than that.",
            setOf(DRUID, RANGER)),
        SpellDef("crown_of_madness", "Crown of Madness", 2, "Enchantment", "Action", "60 feet", "V, S", "1 minute",
            "One creature makes a Wisdom saving throw or has the Charmed condition. On each of its turns it must attack one creature you mentally choose, and it can take no other action.",
            setOf(BARD, SORCERER, WARLOCK, WIZARD), saveAbility = Ability.WIS, concentration = true),
        SpellDef("prayer_of_healing", "Prayer of Healing", 2, "Abjuration", "10 minutes", "30 feet", "V", "Instantaneous",
            "Up to five creatures of your choice each regain Hit Points equal to 2d8 plus your spellcasting ability modifier.",
            setOf(BARD, CLERIC, PALADIN)),
        SpellDef("enthrall", "Enthrall", 2, "Enchantment", "Action", "60 feet", "V, S", "1 minute",
            "Each creature you choose makes a Wisdom saving throw. On a failure it has Disadvantage on Wisdom (Perception) checks to perceive anything other than you.",
            setOf(BARD, WARLOCK), saveAbility = Ability.WIS),
        SpellDef("cordon_of_arrows", "Cordon of Arrows", 2, "Transmutation", "Action", "5 feet", "V, S, M", "8 hours",
            "You plant four pieces of nonmagical ammunition in the ground. When a creature other than you comes within 30 feet of them for the first time on a turn, one piece flies up to strike it for 2d4 Piercing damage on a failed Dexterity save.",
            setOf(RANGER), damage = "2d4", damageType = "Piercing", saveAbility = Ability.DEX),
        SpellDef("nystuls_magic_aura", "Nystul's Magic Aura", 2, "Illusion", "1 minute", "Touch", "V, S, M", "24 hours",
            "You place an illusion on a creature or object you touch, making it register falsely to divination magic or appear to be a different kind of creature.",
            setOf(WIZARD)),

        // ---- Level 3
        SpellDef("conjure_animals", "Conjure Animals", 3, "Conjuration", "Action", "Self", "V, S", "10 minutes",
            "You conjure nature spirits that flit around you in a 10-foot Emanation for the duration. Whenever the Emanation enters a creature's space and whenever a creature enters it or ends its turn there, that creature takes 2d8 Slashing damage on a failed Dexterity save.",
            setOf(DRUID, RANGER), damage = "2d8", damageType = "Slashing", saveAbility = Ability.DEX, concentration = true),
        SpellDef("magic_circle", "Magic Circle", 3, "Abjuration", "1 minute", "10 feet", "V, S, M", "1 hour",
            "You create a 10-foot-radius, 20-foot-tall Cylinder of magical energy. Choose a creature type; those creatures can't willingly enter the Cylinder, and have Disadvantage on attack rolls against creatures inside it.",
            setOf(CLERIC, PALADIN, WARLOCK, WIZARD)),
        SpellDef("major_image", "Major Image", 3, "Illusion", "Action", "120 feet", "V, S, M", "10 minutes",
            "You create the image of an object, creature, or other visible phenomenon no larger than a 20-foot Cube, complete with sound, smell, and temperature.",
            setOf(BARD, SORCERER, WARLOCK, WIZARD), concentration = true),
        SpellDef("slow", "Slow", 3, "Transmutation", "Action", "120 feet", "V, S, M", "1 minute",
            "You alter time around up to six creatures in a 40-foot Cube. Each makes a Wisdom saving throw; on a failure its Speed is halved, it takes a -2 penalty to AC and Dexterity saves, and it can't take Reactions.",
            setOf(BARD, SORCERER, WIZARD), saveAbility = Ability.WIS, concentration = true),
        SpellDef("blinding_smite", "Blinding Smite", 3, "Transmutation", "Bonus Action", "Self", "V", "1 minute",
            "The next time you hit with a Melee weapon, the target takes an extra 3d8 Radiant damage and must succeed on a Constitution saving throw or have the Blinded condition until the spell ends.",
            setOf(PALADIN), damage = "3d8", damageType = "Radiant", saveAbility = Ability.CON, concentration = true),
        SpellDef("meld_into_stone", "Meld into Stone", 3, "Transmutation", "Action or Ritual", "Touch", "V, S", "8 hours",
            "You step into a stone object or surface large enough to fully contain you, melding yourself and your equipment with the stone for the duration.",
            setOf(CLERIC, DRUID), ritual = true),
        SpellDef("feign_death", "Feign Death", 3, "Necromancy", "Action or Ritual", "Touch", "V, S, M", "1 hour",
            "A willing creature you touch appears dead: it has the Incapacitated condition, its Speed is 0, and it has Resistance to all damage except Psychic.",
            setOf(BARD, CLERIC, DRUID, WIZARD), ritual = true),

        // ---- Level 4
        SpellDef("conjure_woodland_beings", "Conjure Woodland Beings", 4, "Conjuration", "Action", "Self", "V, S", "10 minutes",
            "You conjure nature spirits in a 15-foot Emanation. Creatures that start their turn there have their Speed halved, and once per turn you can deal 5d8 Force damage to one creature in it.",
            setOf(DRUID, RANGER), damage = "5d8", damageType = "Force", concentration = true),
        SpellDef("grasping_vine", "Grasping Vine", 4, "Conjuration", "Bonus Action", "60 feet", "V, S", "1 minute",
            "You conjure a vine that sprouts from the ground. When you cast it, and as a Bonus Action on later turns, you can direct it to seize a creature within 30 feet of it, which takes 4d8 Bludgeoning damage and is pulled up to 20 feet on a failed Dexterity save.",
            setOf(DRUID, RANGER), damage = "4d8", damageType = "Bludgeoning", saveAbility = Ability.DEX, concentration = true),
        SpellDef("divination", "Divination", 4, "Divination", "Action or Ritual", "Self", "V, S, M", "Instantaneous",
            "You put one question about a specific goal, event, or activity to occur within 7 days to a divine power, and receive a truthful reply — a short phrase, a cryptic rhyme, or an omen.",
            setOf(CLERIC), ritual = true),
        SpellDef("evards_black_tentacles", "Evard's Black Tentacles", 4, "Conjuration", "Action", "90 feet", "V, S, M", "1 minute",
            "Writhing black tentacles fill a 20-foot square. Each creature there makes a Strength saving throw or takes 3d6 Bludgeoning damage and has the Restrained condition.",
            setOf(WIZARD), damage = "3d6", damageType = "Bludgeoning", saveAbility = Ability.STR, concentration = true),

        // ---- Level 5
        SpellDef("geas", "Geas", 5, "Enchantment", "1 minute", "60 feet", "V", "30 days",
            "You place a magical command on a creature that can understand you. It makes a Wisdom saving throw or takes 5d10 Psychic damage whenever it acts in a manner directly counter to your instructions.",
            setOf(BARD, CLERIC, DRUID, PALADIN, WIZARD), damage = "5d10", damageType = "Psychic", saveAbility = Ability.WIS),
        SpellDef("planar_binding", "Planar Binding", 5, "Abjuration", "1 hour", "60 feet", "V, S, M", "24 hours",
            "You bind a Celestial, Elemental, Fey, or Fiend to your service. It makes a Charisma saving throw or is bound to obey your commands for the duration.",
            setOf(BARD, CLERIC, DRUID, WIZARD), saveAbility = Ability.CHA),
        SpellDef("swift_quiver", "Swift Quiver", 5, "Transmutation", "Bonus Action", "Self", "V, S, M", "1 minute",
            "Your quiver produces its own ammunition. On each of your turns until the spell ends, you can take a Bonus Action to make two attacks with a weapon that uses ammunition.",
            setOf(RANGER), concentration = true),
        SpellDef("conjure_volley", "Conjure Volley", 5, "Conjuration", "Action", "150 feet", "V, S, M", "Instantaneous",
            "You brandish a weapon and choose a point within range. Hundreds of similar spectral weapons rain down in a 40-foot-radius, 20-foot-high Cylinder, dealing 8d8 Force damage on a failed Dexterity save or half as much on a success.",
            setOf(RANGER), damage = "8d8", damageType = "Force", saveAbility = Ability.DEX),
        SpellDef("dream", "Dream", 5, "Illusion", "1 minute", "Special", "V, S, M", "8 hours",
            "You shape a creature's dreams. You or a willing messenger enters a trance and appears in the target's dreams, able to converse with it and, if you choose, terrify it so that it gains no benefit from the rest.",
            setOf(BARD, WARLOCK, WIZARD)),
        SpellDef("reincarnate", "Reincarnate", 5, "Necromancy", "1 hour", "Touch", "V, S, M", "Instantaneous",
            "You touch a dead Humanoid or a piece of one. A new adult body forms for the soul, and the creature returns to life with all its Hit Points, though its species may change.",
            setOf(DRUID)),

        // ------------------------------------------------- Imported: Level 1
        SpellDef("buzzing_bee", "Buzzing Bee", 1, "Conjuration", "Action", "120 feet", "V, S, M (a dab of honey)", "1 minute",
            "You call forth a noisy spectral bee. You target a creature that you can see within range. The bee hovers around the target, distracting it with loud buzzing. For the duration, the target has Disadvantage on Wisdom (Perception) checks, Dexterity (Stealth) checks, and Constitution saving throws made to maintain Concentration. In addition, the target cannot benefit from the Invisible condition. The bee moves with the target, hovering within 3 feet of it as long as the target is within 120 feet of you. The bee disappears when the spell ends or if the target moves out of range.",
            setOf(DRUID, RANGER, SORCERER, WIZARD), concentration = true, book = Sourcebook.DDB_DROPS),
        SpellDef("create_or_destroy_water", "Create or Destroy Water", 1, "Transmutation", "Action", "30 feet", "V, S, M (a mix of water and sand)", "Instantaneous",
            "You do one of the following: Create Water. You create up to 10 gallons of clean water within range in an open container. Alternatively, the water falls as rain in a 30-foot Cube within range, extinguishing exposed flames there. Destroy Water. You destroy up to 10 gallons of water in an open container within range. Alternatively, you destroy fog in a 30-foot Cube within range. Using a Higher-Level Spell Slot. You create or destroy 10 additional gallons of water, or the size of the Cube increases by 5 feet, for each spell slot level above 1.",
            setOf(CLERIC, DRUID)),
        SpellDef("insidious_rhythm", "Insidious Rhythm", 1, "Enchantment", "Action", "120 feet", "V, S", "1 minute",
            "One creature of your choice that you can see within range hears a haunting yet catchy tune that continuously repeats in its mind. The target must succeed on a Wisdom saving throw, or it has Disadvantage on Intelligence checks and on Constitution saving throws made to maintain Concentration. At the end of each of its turns, the target repeats the save, ending the spell on itself on a success. Using a Higher-Level Spell Slot. You can target one additional creature for each spell slot level above 1.",
            setOf(BARD), concentration = true, book = Sourcebook.DDB_DROPS),
        SpellDef("spellfire_flare", "Spellfire Flare", 1, "Evocation", "Action", "60 feet", "V, S", "Instantaneous",
            "You unleash a blast of brilliant fire. Make a ranged spell attack against a target within range; a target gains no benefit from Half Cover or Three-Quarters Cover for this attack roll. On a hit, the target takes 2d10 Radiant damage. Using a Higher-Level Spell Slot. You create an additional blast for each spell slot level above 1. You can direct the blasts at the same target or at different ones. Make a separate attack roll for each blast.",
            setOf(SORCERER, WIZARD), book = Sourcebook.HEROES_OF_FAERUN),
        SpellDef("wardaway", "Wardaway", 1, "Abjuration", "Action", "60 feet", "V, S, M (a miniature clay hand)", "Instantaneous",
            "You hurl a disorienting magical force toward one creature within range. The target makes a Constitution saving throw; Constructs and Undead automatically succeed on this save. On a failed save, the target takes 2d4 Force damage, its Speed is halved until the start of your next turn, and on its next turn, it can take only an action or a Bonus Action (but not both). On a successful save, the target takes half as much damage only. Using a Higher-Level Spell Slot. The damage increases by 2d4 for every spell slot level above 1.",
            setOf(BARD, CLERIC, PALADIN, WIZARD), book = Sourcebook.HEROES_OF_FAERUN),

        // ------------------------------------------------- Imported: Level 2
        SpellDef("cloud_of_daggers", "Cloud Of Daggers", 2, "Conjuration", "Action", "60 feet", "V, S, M (a sliver of glass)", "1 minute",
            "You conjure spinning daggers in a 5-foot Cube centered on a point within range. Each creature in that area takes 4d4 Slashing damage. A creature also takes this damage if it enters the Cube or ends its turn there or if the Cube moves into its space. A creature takes this damage only once per turn. On your later turns, you can take a Magic action to teleport the Cube up to 30 feet. Using a Higher-Level Spell Slot. The damage increases by 2d4 for each spell slot level above 2.",
            setOf(BARD, SORCERER, WARLOCK, WIZARD), concentration = true),
        SpellDef("death_armor", "Death Armor", 2, "Necromancy", "Action", "Touch", "V, S, M (an onyx worth 50+ GP, which the spell consumes)", "1 hour",
            "For the duration, an inky aura surrounds one creature you touch. The target has Advantage on Death Saving Throws, and once per turn, when a creature within 5 feet of the target hits it with a melee attack roll, the attacker takes 2d4 Necrotic damage.",
            setOf(SORCERER, WIZARD), book = Sourcebook.HEROES_OF_FAERUN),
        SpellDef("deryan_s_helpful_homunculi", "Deryan's Helpful Homunculi", 2, "Conjuration", "Action or Ritual", "Self", "V, S, M (powdered gemstones worth 100+ GP, which the spell consumes, and one set of Artisan’s Tools with which you have proficiency)", "8 hours",
            "You summon a group of helpful spirits, which lasts for the duration. The spirits appear as homunculi or as another Construct of your choice but are intangible and invulnerable, and they are considered to have proficiency in the Arcana skill and with the set of Artisan's Tools used in the spell's casting. If you are crafting an item, the spirits function as a single assistant for your crafting, halving the crafting time.",
            setOf(CLERIC, WIZARD), ritual = true, book = Sourcebook.HEROES_OF_FAERUN),
        SpellDef("elminster_s_elusion", "Elminster's Elusion", 2, "Abjuration", "Bonus Action", "Self", "V, S", "10 minutes",
            "Arcane wards protect you against magic for the duration. You have Advantage on saving throws against spells and magical effects. Additionally, if you succeed on a saving throw against a spell or magical effect and would normally take half as much damage, you instead take no damage.",
            setOf(WIZARD), concentration = true, book = Sourcebook.HEROES_OF_FAERUN),
        SpellDef("find_traps", "Find Traps", 2, "Divination", "Action", "120 feet", "V, S", "Instantaneous",
            "You sense any trap within range that is within line of sight. A trap, for the purpose of this spell, includes any object or mechanism that was created to cause damage or other danger. Thus, the spell would sense the Alarm or Glyph of Warding spell or a mechanical pit trap, but it wouldn't reveal a natural weakness in the floor, an unstable ceiling, or a hidden sinkhole. This spell reveals that a trap is present but not its location. You do learn the general nature of the danger posed by a trap you sense.",
            setOf(CLERIC, DRUID, RANGER)),
        SpellDef("flame_blade", "Flame Blade", 2, "Evocation", "Bonus Action", "Self", "V, S, M (a sumac leaf)", "10 minutes",
            "You evoke a fiery blade in your free hand. The blade is similar in size and shape to a scimitar, and it lasts for the duration. If you let go of the blade, it disappears, but you can evoke it again as a Bonus Action. As a Magic action, you can make a melee spell attack with the fiery blade. On a hit, the target takes Fire damage equal to 3d6 plus your spellcasting ability modifier. The flaming blade sheds Bright Light in a 10-foot radius and Dim Light for an additional 10 feet. Using a Higher-Level Spell Slot. The damage increases by 1d6 for each spell slot level above 2.",
            setOf(DRUID, SORCERER), concentration = true),
        SpellDef("locate_animals_or_plants", "Locate Animals or Plants", 2, "Divination", "Action or Ritual", "Self", "V, S, M (fur from a bloodhound)", "Instantaneous",
            "Describe or name a specific kind of Beast, Plant creature, or nonmagical plant. You learn the direction and distance to the closest creature or plant of that kind within 5 miles, if any are present.",
            setOf(BARD, DRUID, RANGER), ritual = true),
        SpellDef("searing_orb", "Searing Orb", 2, "Evocation", "Action", "60 feet", "S, M (Metallic flakes and a pinch of phosphorus)", "Instantaneous",
            "You create and hurl a pulsing orb of energy at one creature within range. Make a ranged spell attack against the target. On a hit, the target takes 3d4 Radiant damage. Hit or miss, the orb then explodes in a flash of light. The target and each creature within 10 feet of it make a Constitution saving throw. On a failed save, a creature has the Blinded condition until the end of its next turn. Using a Higher-Level Spell Slot. The damage increases by 1d4 for each spell slot level above 2.",
            setOf(CLERIC, PALADIN), book = Sourcebook.DDB_DROPS),
        SpellDef("tortoise_shell", "Tortoise Shell", 2, "Abjuration", "Action", "Touch", "V, S", "1 minute",
            "You touch a willing creature. Until the spell ends, the target's skin hardens into a tortoise shell while it remains in place, and the target gains a +3 bonus to AC. If the target moves using its action, Bonus Action, Reaction, or movement, the bonus becomes +1 instead until the start of its next turn.",
            setOf(ARTIFICER, DRUID, RANGER), concentration = true, book = Sourcebook.DDB_DROPS),

        // ------------------------------------------------- Imported: Level 3
        SpellDef("astral_flood", "Astral Flood", 3, "Evocation", "Action", "Self", "V, S, M (a mixture of water and powdered silver)", "Instantaneous",
            "You channel energy from the Astral Sea to unleash a torrent of magic from yourself. Choose Cold or Radiant for the type of energy channeled. Each creature in a 30-foot Cone originating from you makes a Dexterity saving throw. On a failed save, the target takes 4d10 damage of the chosen type and suffers an additional effect determined by the damage type: Cold Damage. The target has Disadvantage on the next D20 Test it makes before the end of your next turn. Radiant Damage. The target has the Blinded condition until the end of your next turn. On a successful save, the target takes half as much damage only. Using a Higher-Level Spell Slot: The damage increases by 1d10 for each spell slot above 3.",
            setOf(BARD, CLERIC, SORCERER, WARLOCK, WIZARD), book = Sourcebook.DDB_DROPS),
        SpellDef("cacophonic_shield", "Cacophonic Shield", 3, "Evocation", "Action", "Self", "V, S", "10 minutes",
            "Thunderous reverberations fill a 10-foot Emanation originating from you for the duration. Whenever the Emanation enters a creature's space and whenever a creature enters the Emanation or ends its turn there, the creature makes a Constitution saving throw. On a failed save, the creature takes 3d6 Thunder damage and has the Deafened condition until the start of your next turn. On a successful save, the creature takes half as much damage only. A creature makes this save only once per turn. When you cast this spell, you can designate creatures to be unaffected by it. In addition, you have Resistance to Thunder damage, and ranged attack rolls against you are made with Disadvantage. Using a Higher-Level Spell Slot. The damage increases by 1d6 for each spell slot level above 3.",
            setOf(BARD, SORCERER, WIZARD), concentration = true, book = Sourcebook.HEROES_OF_FAERUN),
        SpellDef("conjure_constructs", "Conjure Constructs", 3, "Conjuration", "Action", "60 feet", "V, S, M (a brass cog)", "10 minutes",
            "You conjure a group of intangible, orderly spirits that appear as a Medium group of modrons or other Constructs in an unoccupied space you can see within range. The spirits last for the duration. When you cast this spell and as a Magic action on subsequent turns, you can command the spirits to target one creature or object you can see within 5 feet of the spirits and create one of the following effects: Clockwork Force. The target makes a Dexterity saving throw, taking 3d6 Force damage on a failed save or half as much damage on a successful one. Orderly Ward. The target gains Temporary Hit Points equal to 1d6 plus your spellcasting ability modifier. When you move on your turn, you can also move the spirits up to 30 feet to an unoccupied space you can see. Using a Higher-Level Spell Slot. The damage and Temporary Hit Points both increase by 1d6 for each spell slot level above 3.",
            setOf(WIZARD), concentration = true, book = Sourcebook.HEROES_OF_FAERUN),
        SpellDef("laeral_s_silver_lance", "Laeral's Silver Lance", 3, "Evocation", "Action", "Self", "V, S, M (a silver pin worth 250+ GP)", "Instantaneous",
            "Silver energy bursts out from you in a 120-foot-long, 5-foot-wide Line. Each creature of your choice in the Line makes a Strength saving throw. On a failed save, a creature takes 3d10 Force damage and has the Prone condition. On a successful save, a creature takes half as much damage only. Using a Higher-Level Spell Slot. The damage increases by 1d10 for every spell slot level above 3.",
            setOf(CLERIC, SORCERER, WIZARD), book = Sourcebook.HEROES_OF_FAERUN),
        SpellDef("leomund_s_tiny_hut", "Leomund's Tiny Hut", 3, "Evocation", "1 minute or Ritual", "Self", "V, S, M (a crystal bead)", "8 hours",
            "A 10-foot Emanation springs into existence around you and remains stationary for the duration. The spell fails when you cast it if the Emanation isn't big enough to fully encapsulate all creatures in its area. Creatures and objects within the Emanation when you cast the spell can move through it freely. All other creatures and objects are barred from passing through it. Spells of level 3 or lower can't be cast through it, and the effects of such spells can't extend into it. The atmosphere inside the Emanation is comfortable and dry, regardless of the weather outside. Until the spell ends, you can command the interior to have Dim Light or Darkness (no action required). The Emanation is opaque from the outside and of any color you choose, but it's transparent from the inside. The spell ends early if you leave the Emanation or if you cast it again.",
            setOf(BARD, WIZARD), ritual = true),
        SpellDef("lightning_arrow", "Lightning Arrow", 3, "Transmutation", "Bonus Action, which you take immediately after hitting or missing a target with a ranged attack using a weapon", "Self", "V, S", "Instantaneous",
            "As your attack hits or misses the target, the weapon or ammunition you're using transforms into a lightning bolt. Instead of taking any damage or other effects from the attack, the target takes 4d8 Lightning damage on a hit or half as much damage on a miss. Each creature within 10 feet of the target then makes a Dexterity saving throw, taking 2d8 Lightning damage on a failed save or half as much damage on a successful one. The weapon or ammunition then returns to its normal form. Using a Higher-Level Spell Slot. The damage for both effects of the spell increases by 1d8 for each spell slot level above 3.",
            setOf(RANGER)),
        SpellDef("speak_with_plants", "Speak with Plants", 3, "Transmutation", "Action", "Self", "V, S", "10 minutes",
            "You imbue plants in an immobile 30-foot Emanation with limited sentience and animation, giving them the ability to communicate with you and follow your simple commands. You can question plants about events in the spell's area within the past day, gaining information about creatures that have passed, weather, and other circumstances. You can also turn Difficult Terrain caused by plant growth (such as thickets and undergrowth) into ordinary terrain that lasts for the duration. Or you can turn ordinary terrain where plants are present into Difficult Terrain that lasts for the duration. The spell doesn't enable plants to uproot themselves and move about, but they can move their branches, tendrils, and stalks for you. If a Plant creature is in the area, you can communicate with it as if you shared a common language.",
            setOf(BARD, DRUID, RANGER)),
        SpellDef("sylune_s_viper", "Sylune's Viper", 3, "Conjuration", "Bonus Action", "Self", "V, S, M (a snake fang)", "1 hour",
            "A shimmering, spectral snake encircles your body for the duration. You gain 15 Temporary Hit Points; the spell ends early if you have no Temporary Hit Points left. While the spell is active, you gain the following benefits: Climbing. You gain a Climb Speed equal to your Speed. Venomous Bite. As a Magic action, you can make a ranged spell attack using the snake against one creature within 50 feet. On a hit, the target takes 1d6 Force damage and has the Poisoned condition until the start of your next turn. While Poisoned, the target has the Incapacitated condition. Using a Higher-Level Spell Slot. For each spell slot level above 3, the number of Temporary Hit Points you gain from this spell increases by 5, and the damage of Venomous Bite increases by 1d6.",
            setOf(DRUID, WIZARD), book = Sourcebook.HEROES_OF_FAERUN),

        // ------------------------------------------------- Imported: Level 4
        SpellDef("backlash", "Backlash", 4, "Abjuration", "Reaction, which you take in response to taking damage", "60 feet", "V", "Instantaneous",
            "You ward yourself against destructive energy, reducing the damage taken by 4d6 plus your spellcasting ability modifier. If the triggering damage was from a creature within range, you can force the creature to make a Constitution saving throw. The creature takes 4d6 Force damage on a failed save or half as much damage on a successful one. Using a Higher-Level Spell Slot. The damage reduction and Force damage from this spell both increase by 1d6 for every spell slot level above 4.",
            setOf(BARD, SORCERER, WARLOCK, WIZARD), book = Sourcebook.HEROES_OF_FAERUN),
        SpellDef("doomtide", "Doomtide", 4, "Conjuration", "Action", "120 feet", "V, S, M (soot and a dried eel)", "1 minute",
            "You create a 20-foot-radius Sphere of inky fog within range. The fog is magical Darkness and lasts for the duration or until a strong wind (such as the one created by the Gust of Wind spell) disperses it, ending the spell. Each creature in the Sphere when it appears makes a Wisdom saving throw. On a failed save, a creature takes 5d6 Psychic damage and subtracts 1d6 from its saving throws until the end of its next turn. On a successful save, a creature takes half as much damage only. A creature also makes this save when the Sphere moves into its space, when it enters the Sphere, or when it ends its turn inside the Sphere. A creature makes this save only once per turn. The Sphere moves 10 feet away from you at the start of each of your turns. Casting as a Circle Spell. Casting this as a Circle spell requires a minimum of five secondary casters. In addition to the spell's usual components, you must provide a special component (a string of three black pearls from Pandemonium), which the spell consumes. The spell's range increases to 1 mile, and its duration increases to until dispelled (no Concentration required). [...]",
            setOf(BARD, CLERIC, WARLOCK), concentration = true, book = Sourcebook.HEROES_OF_FAERUN),
        SpellDef("fount_of_moonlight", "Fount of Moonlight", 4, "Evocation", "Action", "Self", "V, S", "10 minutes",
            "A cool light wreathes your body for the duration, emitting Bright Light in a 20-foot radius and Dim Light for an additional 20 feet. Until the spell ends, you have Resistance to Radiant damage, and your melee attacks deal an extra 2d6 Radiant damage on a hit. In addition, immediately after you take damage from a creature you can see within 60 feet of yourself, you can take a Reaction to force the creature to make a Constitution saving throw. On a failed save, the creature has the Blinded condition until the end of your next turn.",
            setOf(BARD, DRUID), concentration = true),
        SpellDef("spellfire_storm", "Spellfire Storm", 4, "Evocation", "Action", "60 feet", "V, S", "1 minute",
            "You conjure a pillar of spellfire in a 20-foot-radius, 20-foot-high Cylinder centered on a point within range. The area of the Cylinder is Bright Light, and each creature in it when it appears makes a Constitution saving throw, taking 4d10 Radiant damage on a failed save or half as much damage on a successful one. A creature also makes this save when it enters the spell's area for the first time on a turn or ends its turn there. A creature makes this save only once per turn. In addition, whenever a creature in the Cylinder casts a spell, that creature makes a Constitution saving throw. On a failed save, the spell dissipates with no effect, and the action, Bonus Action, or Reaction used to cast it is wasted. If that spell was cast with a spell slot, the slot isn't expended. When you cast this spell, you can designate creatures to be unaffected by it. Casting as a Circle Spell. In addition to the spell's usual components, you must provide a special component (a blue star sapphire worth 25,000+ GP), which the spell consumes. The spell's range increases to 1 mile, and it no longer requires Concentration. [...]",
            setOf(SORCERER, WIZARD), concentration = true, book = Sourcebook.HEROES_OF_FAERUN),
        SpellDef("sticks_to_snakes", "Sticks to Snakes", 4, "Transmutation", "Action", "90 feet", "V, S, M (a small piece of bark and several snake scales)", "1 minute",
            "You can choose up to four nonmagical sticks no longer than a Quarterstaff (or similar pieces of nonmagical wood, such as Torches, Spears, etc.) that you can see within range to shape-shift into snakes. Creatures that are holding a targeted object can make a Charisma saving throw, preventing the target from shape-shifting on a success. Each shape-shifted target uses the Venomous Snake stat block. Each of these snakes is Friendly to you and your allies. In combat, it shares your Initiative count and takes its turn immediately after yours. Until the spell ends, you can take a Bonus Action to mentally command any creature you made with this spell if the creature is within 500 feet of you (if you control multiple creatures, you can command any of them at the same time, issuing the same command to each one). If you issue no commands, the creature takes the Dodge action and moves only to avoid harm. When the creature drops to 0 Hit Points, it reverts to its object form, and any remaining damage carries over to that form. Using a Higher-Level Spell Slot. You can target two additional objects for each spell slot level above 4.",
            setOf(CLERIC, DRUID, RANGER), concentration = true, book = Sourcebook.DDB_DROPS),

        // ------------------------------------------------- Imported: Level 5
        SpellDef("alustriel_s_mooncloak", "Alustriel's Mooncloak", 5, "Abjuration", "Action", "Self", "V, S, M (a moonstone worth 50+ GP)", "1 minute",
            "For the duration, moonlight fills a 20-foot Emanation originating from you with Dim Light. While in that area, you and your allies have Half Cover and Resistance to Cold, Lightning, and Radiant damage. While the spell lasts, you can use one of the following options, ending the spell immediately: Liberation. When you fail a saving throw to avoid or end the Frightened, Grappled, or Restrained condition, you can take a Reaction to succeed on the save instead. Respite. As a Magic action, you or an ally within the area regains Hit Points equal to 4d10 plus your spellcasting ability modifier.",
            setOf(BARD, DRUID, RANGER, WIZARD), concentration = true, book = Sourcebook.HEROES_OF_FAERUN),
        SpellDef("jallarzi_s_storm_of_radiance", "Jallarzi's Storm of Radiance", 5, "Evocation", "Action", "120 feet", "V, S, M (a pinch of phosphorus)", "1 minute",
            "You unleash a storm of flashing light and raging thunder in a 10-foot-radius, 40-foot-high Cylinder centered on a point you can see within range. While in this area, creatures have the Blinded and Deafened conditions, and they can't cast spells with a Verbal component. When the storm appears, each creature in it makes a Constitution saving throw, taking 2d10 Radiant damage and 2d10 Thunder damage on a failed save or half as much damage on a successful one. A creature also makes this save when it enters the spell's area for the first time on a turn or ends its turn there. A creature makes this save only once per turn. Using a Higher-Level Spell Slot. The Radiant and Thunder damage increase by 1d10 for each spell slot level above 5.",
            setOf(WARLOCK, WIZARD), concentration = true),
        SpellDef("rary_s_telepathic_bond", "Rary's Telepathic Bond", 5, "Divination", "Action or Ritual", "30 feet", "V, S, M (two eggs)", "1 hour",
            "You forge a telepathic link among up to eight willing creatures of your choice within range, psychically linking each creature to all the others for the duration. Creatures that can't communicate in any languages aren't affected by this spell. Until the spell ends, the targets can communicate telepathically through the bond whether or not they share a language. The communication is possible over any distance, though it can't extend to other planes of existence.",
            setOf(BARD, WIZARD), ritual = true),
        SpellDef("songal_s_elemental_suffusion", "Songal's Elemental Suffusion", 5, "Transmutation", "Action", "Self", "V, S, M (a pearl worth 100+ GP)", "1 minute",
            "You imbue yourself with the elemental power of genies. You gain the following benefits until the spell ends: Elemental Immunity. When you cast this spell, choose one of the following damage types: Acid, Cold, Fire, Lightning, or Thunder. You have Resistance to the chosen damage type. Elemental Pulse. When you cast this spell and at the start of each of your subsequent turns, you release a burst of elemental energy in a 15-foot Emanation originating from yourself. Each creature of your choice in that area makes a Dexterity saving throw. On a failed save, a creature takes 2d6 Acid, Cold, Fire, Lightning, or Thunder damage (your choice) and has the Prone condition. On a successful save, a creature takes half as much damage only. Flight. You gain a Fly Speed of 30 feet and can hover. Casting as a Circle Spell. If the spell is cast as a Circle spell, its casting time increases to 1 minute, and its duration increases to Concentration, up to 10 minutes. For each secondary caster who participates in the casting, you can choose one additional creature, to a maximum of nine additional creatures. The chosen creatures also gain the benefits of the spell for its duration. [...]",
            setOf(DRUID, SORCERER, WIZARD), concentration = true, book = Sourcebook.HEROES_OF_FAERUN),
        SpellDef("yolande_s_regal_presence", "Yolande's Regal Presence", 5, "Enchantment", "Action", "Self", "Component: V, S, M (a miniature tiara)", "1 minute",
            "You surround yourself with unearthly majesty in a 10-foot Emanation. Whenever the Emanation enters the space of a creature you can see and whenever a creature you can see enters the Emanation or ends its turn there, you can force that creature to make a Wisdom saving throw. On a failed save, the target takes 4d6 Psychic damage and has the Prone condition, and you can push it up to 10 feet away. On a successful save, the target takes half as much damage only. A creature makes this save only once per turn.",
            setOf(BARD, WIZARD), concentration = true),

        // ------------------------------------------------- Imported: Level 6
        SpellDef("arcane_gate", "Arcane Gate", 6, "Conjuration", "Action", "500 feet", "V, S", "10 minutes",
            "You create linked teleportation portals. Choose two Large, unoccupied spaces on the ground that you can see, one space within range and the other one within 10 feet of you. A circular portal opens in each of those spaces and remains for the duration. The portals are two-dimensional glowing rings filled with mist that blocks sight. They hover inches from the ground and are perpendicular to it. A portal is open on only one side (you choose which). Anything entering the open side of a portal exits from the open side of the other portal as if the two were adjacent to each other. As a Bonus Action, you can change the facing of the open sides.",
            setOf(SORCERER, WARLOCK, WIZARD), concentration = true),
        SpellDef("blade_barrier", "Blade Barrier", 6, "Evocation", "Action", "90 feet", "V, S", "10 minutes",
            "You create a wall of whirling blades made of magical energy. The wall appears within range and lasts for the duration. You make a straight wall up to 100 feet long, 20 feet high, and 5 feet thick, or a ringed wall up to 60 feet in diameter, 20 feet high, and 5 feet thick. The wall provides Three-Quarters Cover, and its space is Difficult Terrain. Any creature in the wall's space makes a Dexterity saving throw, taking 6d10 Force damage on a failed save or half as much damage on a successful one. A creature also makes that save if it enters the wall's space or ends it turn there. A creature makes that save only once per turn.",
            setOf(CLERIC), concentration = true),
        SpellDef("chain_lightning", "Chain Lightning", 6, "Evocation", "Action", "150 feet", "V, S, M (three silver pins)", "Instantaneous",
            "You launch a lightning bolt toward a target you can see within range. Three bolts then leap from that target to as many as three other targets of your choice, each of which must be within 30 feet of the first target. A target can be a creature or an object and can be targeted by only one of the bolts. Each target makes a Dexterity saving throw, taking 10d8 Lightning damage on a failed save or half as much damage on a successful one. Using a Higher-Level Spell Slot. One additional bolt leaps from the first target to another target for each spell slot level above 6.",
            setOf(SORCERER, WIZARD)),
        SpellDef("circle_of_death", "Circle Of Death", 6, "Necromancy", "Action", "150 feet", "V, S, M (the powder of a crushed black pearl worth 500+ GP)", "Instantaneous",
            "Negative energy ripples out in a 60-foot-radius Sphere from a point you choose within range. Each creature in that area makes a Constitution saving throw, taking 8d8 Necrotic damage on a failed save or half as much damage on a successful one. Using a Higher-Level Spell Slot. The damage increases by 2d8 for each spell slot level above 6.",
            setOf(SORCERER, WARLOCK, WIZARD)),
        SpellDef("conjure_fey", "Conjure Fey", 6, "Conjuration", "Action", "60 feet", "V, S", "10 minutes",
            "You conjure a Medium spirit from the Feywild in an unoccupied space you can see within range. The spirit lasts for the duration, and it looks like a Fey creature of your choice. When the spirit appears, you can make one melee spell attack against a creature within 5 feet of it. On a hit, the target takes Psychic damage equal to 3d12 plus your spellcasting ability modifier, and the target has the Frightened condition until the start of your next turn, with both you and the spirit as the source of the fear. As a Bonus Action on your later turns, you can teleport the spirit to an unoccupied space you can see within 30 feet of the space it left and make the attack against a creature within 5 feet of it. Using a Higher-Level Spell Slot. The damage increases by 1d12 for each spell slot level above 6.",
            setOf(DRUID), concentration = true),
        SpellDef("contingency", "Contingency", 6, "Abjuration", "10 minutes", "Self", "V, S, M (a gem-encrusted statuette of yourself worth 1,500+ GP)", "10 days",
            "Choose a spell of level 5 or lower that you can cast, that has a casting time of an action, and that can target you. You cast that spell-called the contingent spell-as part of casting Contingency, expending spell slots for both, but the contingent spell doesn't come into effect. Instead, it takes effect when a certain trigger occurs. You describe that trigger when you cast the two spells. For example, a Contingency cast with Water Breathing might stipulate that Water Breathing comes into effect when you are engulfed in water or a similar liquid. The contingent spell takes effect immediately after the trigger occurs for the first time, whether or not you want it to, and then Contingency ends. The contingent spell takes effect only on you, even if it can normally target others. You can use only one Contingency spell at a time. If you cast this spell again, the effect of another Contingency spell on you ends. Also, Contingency ends on you if its material component is ever not on your person.",
            setOf(WIZARD)),
        SpellDef("create_undead", "Create Undead", 6, "Necromancy", "1 minute", "10 feet", "V, S, M (one 150+ GP black onyx stone for each corpse)", "Instantaneous",
            "You can cast this spell only at night. Choose up to three corpses of Medium or Small Humanoids within range. Each one becomes a Ghoul under your control (see the Monster Manual for its stat block). As a Bonus Action on each of your turns, you can mentally command any creature you animated with this spell if the creature is within 120 feet of you (if you control multiple creatures, you can command any of them at the same time, issuing the same command to them). You decide what action the creature will take and where it will move on its next turn, or you can issue a general command, such as to guard a particular place. If you issue no commands, the creature takes the Dodge action and moves only to avoid harm. Once given an order, the creature continues to follow the order until its task is complete. The creature is under your control for 24 hours, after which it stops obeying any command you've given it. To maintain control of the creature for another 24 hours, you must cast this spell on the creature before the current 24-hour period ends. This use of the spell reasserts your control over up to three creatures you have animated with this spell rather than animating new ones. [...]",
            setOf(CLERIC, WARLOCK, WIZARD)),
        SpellDef("dirge", "Dirge", 6, "Enchantment", "Action", "Self", "V", "1 minute",
            "Deathly power fills a 60-foot Emanation originating from you for the duration. When you cast this spell, you can designate creatures to be unaffected by it. Any other creature can't regain Hit Points while in the Emanation. Whenever the Emanation enters a creature's space and whenever a creature enters the Emanation or ends its turn there, the creature makes a Constitution saving throw. On a failed save, the creature takes 3d10 Necrotic damage and has the Prone condition. On a successful save, the creature takes half as much damage and its Speed is halved. A creature makes this save only once per turn. Casting as a Circle Spell. Casting this as a Circle spell requires a minimum of two secondary casters. If the spell is cast as a Circle spell, its duration becomes Concentration, up to 10 minutes. A creature that fails its save against the spell's effect also gains 1 Exhaustion level. While the creature has Exhaustion levels, finishing a Long Rest neither restores lost Hit Points nor reduces the creature's Exhaustion level. When the spell is cast, each secondary caster must expend a level 4+ spell slot; otherwise, the spell fails.",
            setOf(BARD, CLERIC), concentration = true, book = Sourcebook.HEROES_OF_FAERUN),
        SpellDef("disintegrate", "Disintegrate", 6, "Transmutation", "Action", "60 feet", "V, S, M (a lodestone and dust)", "Instantaneous",
            "You launch a green ray at a target you can see within range. The target can be a creature, a nonmagical object, or a creation of magical force, such as the wall created by Wall of Force . A creature targeted by this spell makes a Dexterity saving throw. On a failed save, the target takes 10d6 + 40 Force damage. If this damage reduces it to 0 Hit Points, it and everything nonmagical it is wearing and carrying are disintegrated into gray dust. The target can be revived only by a True Resurrection or a Wish spell. This spell automatically disintegrates a Large or smaller nonmagical object or a creation of magical force. If such a target is Huge or larger, this spell disintegrates a 10-foot-Cube portion of it. Using a Higher-Level Spell Slot. The damage increases by 3d6 for each spell slot level above 6.",
            setOf(SORCERER, WIZARD)),
        SpellDef("drawmij_s_instant_summons", "Drawmij's Instant Summons", 6, "Conjuration", "1 minute or Ritual", "Touch", "V, S, M (a sapphire worth 1,000+ GP)", "Until dispelled",
            "You touch the sapphire used in the casting and an object weighing 10 pounds or less whose longest dimension is 6 feet or less. The spell leaves an Invisible mark on that object and invisibly inscribes the object's name on the sapphire. Each time you cast this spell, you must use a different sapphire. Thereafter, you can take a Magic action to speak the object's name and crush the sapphire. The object instantly appears in your hand regardless of physical or planar distances, and the spell ends. If another creature is holding or carrying the object, crushing the sapphire doesn't transport it, but instead you learn who that creature is and where that creature is currently located.",
            setOf(WIZARD), ritual = true),
        SpellDef("elminster_s_effulgent_spheres", "Elminster's Effulgent Spheres", 6, "Evocation", "Action", "Self", "V, S, M (an opal worth 1,000 GP+)", "1 hour",
            "Six chromatic spheres orbit you for the duration. While the spheres are present, you can expend spheres to create the following effects: Absorb Energy. When you take Acid, Cold, Fire, Lightning, or Thunder damage, you can take a Reaction to expend one sphere and give yourself Resistance to the triggering damage type until the start of your next turn. Energy Blast. As a Bonus Action, you send one sphere hurtling toward a target within 120 feet of yourself. Make a ranged spell attack. On a hit, the target takes 3d6 Acid, Cold, Fire, Lightning, or Thunder damage (your choice). Regardless of whether you hit, the sphere is expended. The spell ends early if you have no more spheres remaining. Using a Higher-Level Spell Slot. The number of spheres increases by 1 for every spell slot level above 6.",
            setOf(DRUID, SORCERER, WIZARD), book = Sourcebook.HEROES_OF_FAERUN),
        SpellDef("eyebite", "Eyebite", 6, "Necromancy", "Action", "Self", "V, S", "1 minute",
            "For the duration, your eyes become an inky void. One creature of your choice within 60 feet of you that you can see must succeed on a Wisdom saving throw or be affected by one of the following effects of your choice for the duration. On each of your turns until the spell ends, you can take a Magic action to target another creature but can't target a creature again if it has succeeded on a save against this casting of the spell. Asleep. The target has the Unconscious condition. It wakes up if it takes any damage or if another creature takes an action to shake it awake. Panicked. The target has the Frightened condition. On each of its turns, the Frightened target must take the Dash action and move away from you by the safest and shortest route available. If the target moves to a space at least 60 feet away from you where it can't see you, this effect ends. Sickened. The target has the Poisoned condition.",
            setOf(BARD, SORCERER, WARLOCK, WIZARD), concentration = true),
        SpellDef("find_the_path", "Find the Path", 6, "Divination", "1 minute", "Self", "V, S, M (a set of divination tools - such as cards or runes - worth 100+ GP)", "1 day",
            "You magically sense the most direct physical route to a location you name. You must be familiar with the location, and the spell fails if you name a destination on another plane of existence, a moving destination (such as a mobile fortress), or an unspecific destination (such as \"a green dragon's lair\"). For the duration, as long as you are on the same plane of existence as the destination, you know how far it is and in what direction it lies. Whenever you face a choice of paths along the way there, you know which path is the most direct.",
            setOf(BARD, CLERIC, DRUID), concentration = true),
        SpellDef("flesh_to_stone", "Flesh to Stone", 6, "Transmutation", "Action", "60 feet", "V, S, M (a cockatrice feather)", "1 minute",
            "You attempt to turn one creature that you can see within range into stone. The target makes a Constitution saving throw. On a failed save, it has the Restrained condition for the duration. On a successful save, its Speed is 0 until the start of your next turn. Constructs automatically succeed on the save. A Restrained target makes another Constitution saving throw at the end of each of its turns. If it successfully saves against this spell three times, the spell ends. If it fails its saves three times, it is turned to stone and has the Petrified condition for the duration. The successes and failures needn't be consecutive; keep track of both until the target collects three of a kind. If you maintain your Concentration on this spell for the entire possible duration, the target is Petrified until the condition is ended by Greater Restoration or similar magic. [...]",
            setOf(DRUID, SORCERER, WIZARD), concentration = true),
        SpellDef("forbiddance", "Forbiddance", 6, "Abjuration", "10 minutes or Ritual", "Touch", "V, S, M (ruby dust worth 1,000+ GP)", "1 day",
            "You create a ward against magical travel that protects up to 40,000 square feet of floor space to a height of 30 feet above the floor. For the duration, creatures can't teleport into the area or use portals, such as those created by the Gate spell, to enter the area. The spell proofs the area against planar travel, and therefore prevents creatures from accessing the area by way of the Astral Plane, the Ethereal Plane, the Feywild, the Shadowfell, or the Plane Shift spell. In addition, the spell damages types of creatures that you choose when you cast it. Choose one or more of the following: Aberrations, Celestials, Elementals, Fey, Fiends, and Undead. When a creature of a chosen type enters the spell's area for the first time on a turn or ends its turn there, the creature takes 5d10 Radiant or Necrotic damage (your choice when you cast this spell). You can designate a password when you cast the spell. A creature that speaks the password as it enters the area takes no damage from the spell. The spell's area can't overlap with the area of another Forbiddance spell. [...]",
            setOf(CLERIC), ritual = true),
        SpellDef("globe_of_invulnerability", "Globe of Invulnerability", 6, "Abjuration", "Action", "Self", "V, S, M (a glass bead)", "1 minute",
            "An immobile, shimmering barrier appears in a 10-foot Emanation around you and remains for the duration. Any spell of level 5 or lower cast from outside the barrier can't affect anything within it. Such a spell can target creatures and objects within the barrier, but the spell has no effect on them. Similarly, the area within the barrier is excluded from areas of effect created by such spells. Using a Higher-Level Spell Slot. The barrier blocks spells of 1 level higher for each spell slot level above 6.",
            setOf(SORCERER, WIZARD), concentration = true),
        SpellDef("guards_and_wards", "Guards and Wards", 6, "Abjuration", "1 hour", "Touch", "V, S, M (a silver rod worth 10+ GP)", "24 hours",
            "You create a ward that protects up to 2,500 square feet of floor space. The warded area can be up to 20 feet tall, and you shape it as one 50-foot square, one hundred 5-foot squares that are contiguous, or twenty-five 10-foot squares that are contiguous. When you cast this spell, you can specify individuals that are unaffected by the spell's effects. You can also specify a password that, when spoken aloud within 5 feet of the warded area, makes the speaker immune to its effects. The spell creates the effects below within the warded area. Dispel Magic has no effect on Guards and Wards itself, but each of the following effects can be dispelled. If all four are dispelled, Guards and Wards ends. If you cast the spell every day for 365 days on the same area, the spell thereafter lasts until all its effects are dispelled. Corridors. Fog fills all the warded corridors, making them Heavily Obscured. In addition, at each intersection or branching passage offering a choice of direction, there is a 50 percent chance that a creature other than you believes it is going in the opposite direction from the one it chooses. Doors. [...]",
            setOf(BARD, WIZARD)),
        SpellDef("harm", "Harm", 6, "Necromancy", "Action", "60 feet", "V, S", "Instantaneous",
            "You unleash virulent magic on a creature you can see within range. The target makes a Constitution saving throw. On a failed save, it takes 14d6 Necrotic damage, and its Hit Point maximum is reduced by an amount equal to the Necrotic damage it took. On a successful save, it takes half as much damage only. This spell can't reduce a target's Hit Point maximum below 1.",
            setOf(CLERIC)),
        SpellDef("heal", "Heal", 6, "Abjuration", "Action", "60 feet", "V, S", "Instantaneous",
            "Choose a creature that you can see within range. Positive energy washes through the target, restoring 70 Hit Points. This spell also ends the Blinded, Deafened, and Poisoned conditions on the target. Using a Higher-Level Spell Slot. The healing increases by 10 for each spell slot level above 6.",
            setOf(CLERIC, DRUID)),
        SpellDef("heroes_feast", "Heroes' Feast", 6, "Conjuration", "10 minutes", "Self", "V, S, M (a gem-encrusted bowl worth 1,000+ GP, which the spell consumes)", "Instantaneous",
            "You conjure a feast that appears on a surface in an unoccupied 10-foot Cube next to you. The feast takes 1 hour to consume and disappears at the end of that time, and the beneficial effects don't set in until this hour is over. Up to twelve creatures can partake of the feast. A creature that partakes gains several benefits, which last for 24 hours. The creature has Resistance to Poison damage, and it has Immunity to the Frightened and Poisoned conditions. Its Hit Point maximum also increases by 2d10, and it gains the same number of Hit Points.",
            setOf(BARD, CLERIC, DRUID)),
        SpellDef("leomund_s_lamentable_belaborment", "Leomund's Lamentable Belaborment", 6, "Enchantment", "Action", "30 feet", "V", "1 Minute",
            "You proclaim an insightful or inflammatory statement, such as a claim about the politics of a nearby town. Each creature in a 10-foot-radius Sphere centered on a point you choose within range must succeed on an Intelligence saving throw or have the Charmed condition until the spell ends. Any creature that doesn't share a language with you or that has an Intelligence score lower than 3 automatically succeeds on the saving throw. While Charmed, a target must spend its turn discussing or arguing for or against your statement. For the duration, the target has a Speed of 0 and has the Blinded and Deafened conditions with respect to everyone except you and other targets affected by this spell. At the end of each of its turns, the target repeats the save, ending the spell on itself on a success.",
            setOf(BARD, SORCERER, WIZARD), book = Sourcebook.DDB_DROPS),
        SpellDef("magic_jar", "Magic Jar", 6, "Necromancy", "1 minute", "Self", "V, S, M (a gem, crystal, or reliquary worth 500+ GP)", "Until dispelled",
            "Your body falls into a catatonic state as your soul leaves it and enters the container you used for the spell's Material component. While your soul inhabits the container, you are aware of your surroundings as if you were in the container's space. You can't move or take Reactions. The only action you can take is to project your soul up to 100 feet out of the container, either returning to your living body (and ending the spell) or attempting to possess a Humanoid's body. You can attempt to possess any Humanoid within 100 feet of you that you can see (creatures warded by a Protection from Evil and Good or Magic Circle spell can't be possessed). The target makes a Charisma saving throw. On a failed save, your soul enters the target's body, and the target's soul becomes trapped in the container. On a successful save, the target resists your efforts to possess it, and you can't attempt to possess it again for 24 hours. Once you possess a creature's body, you control it. Your Hit Points, Hit Point Dice, Strength, Dexterity, Constitution, Speed, and senses are replaced by the creature's. You otherwise keep your game statistics. [...]",
            setOf(WIZARD)),
        SpellDef("mass_suggestion", "Mass Suggestion", 6, "Enchantment", "Action", "60 feet", "V, M (a snake’s tongue)", "24 hours",
            "You suggest a course of activity-described in no more than 25 words-to twelve or fewer creatures you can see within range that can hear and understand you. The suggestion must sound achievable and not involve anything that would obviously deal damage to any of the targets or their allies. For example, you could say, \"Walk to the village down that road, and help the villagers there harvest crops until sunset.\" Or you could say, \"Now is not the time for violence. Drop your weapons, and dance! Stop in an hour.\" Each target must succeed on a Wisdom saving throw or have the Charmed condition for the duration or until you or your allies deal damage to the target. Each Charmed target pursues the suggestion to the best of its ability. The suggested activity can continue for the entire duration, but if the suggested activity can be completed in a shorter time, the spell ends for a target upon completing it. Using a Higher-Level Spell Slot. The duration is longer with a spell slot of level 7 (10 days), 8 (30 days), or 9 (366 days).",
            setOf(BARD, SORCERER, WIZARD)),
        SpellDef("move_earth", "Move Earth", 6, "Transmutation", "Action", "120 feet", "V, S, M (a miniature shovel)", "2 hours",
            "Choose an area of terrain no larger than 40 feet on a side within range. You can reshape dirt, sand, or clay in the area in any manner you choose for the duration. You can raise or lower the area's elevation, create or fill in a trench, erect or flatten a wall, or form a pillar. The extent of any such changes can't exceed half the area's largest dimension. For example, if you affect a 40-foot square, you can create a pillar up to 20 feet high, raise or lower the square's elevation by up to 20 feet, dig a trench up to 20 feet deep, and so on. It takes 10 minutes for these changes to complete. Because the terrain's transformation occurs slowly, creatures in the area can't usually be trapped or injured by the ground's movement. At the end of every 10 minutes you spend concentrating on the spell, you can choose a new area of terrain to affect within range. This spell can't manipulate natural stone or stone construction. Rocks and structures shift to accommodate the new terrain. If the way you shape the terrain would make a structure unstable, it might collapse. Similarly, this spell doesn't directly affect plant growth. The moved earth carries any plants along with it.",
            setOf(DRUID, SORCERER, WIZARD), concentration = true),
        SpellDef("otiluke_s_freezing_sphere", "Otiluke's Freezing Sphere", 6, "Evocation", "Action", "300 feet", "V, S, M (a miniature crystal sphere)", "Instantaneous",
            "A frigid globe streaks from you to a point of your choice within range, where it explodes in a 60-foot-radius Sphere. Each creature in that area makes a Constitution saving throw, taking 10d6 Cold damage on failed save or half as much damage on a successful one. If the globe strikes a body of water, it freezes the water to a depth of 6 inches over an area 30 feet square. This ice lasts for 1 minute. Creatures that were swimming on the surface of frozen water are trapped in the ice and have the Restrained condition. A trapped creature can take an action to make a Strength (Athletics) check against your spell save DC to break free. You can refrain from firing the globe after completing the spell's casting. If you do so, a globe about the size of a sling bullet, cool to the touch, appears in your hand. At any time, you or a creature you give the globe to can throw the globe (to a range of 40 feet) or hurl it with a sling (to the sling's normal range). It shatters on impact, with the same effect as a normal casting of the spell. You can also set the globe down without shattering it. After 1 minute, if the globe hasn't already shattered, it explodes. Using a Higher-Level Spell Slot. [...]",
            setOf(SORCERER, WIZARD)),
        SpellDef("programmed_illusion", "Programmed Illusion", 6, "Illusion", "Action", "120 feet", "V, S, M (jade dust worth 25+ GP)", "Until dispelled",
            "You create an illusion of an object, a creature, or some other visible phenomenon within range that activates when a specific trigger occurs. The illusion is imperceptible until then. It must be no larger than a 30-foot Cube, and you decide when you cast the spell how the illusion behaves and what sounds it makes. This scripted performance can last up to 5 minutes. When the trigger you specify occurs, the illusion springs into existence and performs in the manner you described. Once the illusion finishes performing, it disappears and remains dormant for 10 minutes, after which the illusion can be activated again. The trigger can be as general or as detailed as you like, though it must be based on visual or audible phenomena that occur within 30 feet of the area. For example, you could create an illusion of yourself to appear and warn off others who attempt to open a trapped door. Physical interaction with the image reveals it to be illusory, since things can pass through it. A creature that takes the Study action to examine the image can determine that it is an illusion with a successful Intelligence (Investigation) check against your spell save DC. [...]",
            setOf(BARD, WIZARD)),
        SpellDef("summon_fiend", "Summon Fiend", 6, "Conjuration", "Action", "90 feet", "V, S, M (a bloody vial worth 600+ GP)", "1 hour",
            "You call forth a fiendish spirit. It manifests in an unoccupied space that you can see within range and uses the Fiendish Spirit stat block. When you cast the spell, choose Demon, Devil, or Yugoloth. The creature resembles a Fiend of the chosen type, which determines certain details in its stat block. The creature disappears when it drops to 0 Hit Points or when the spell ends. The creature is an ally to you and your allies. In combat, the creature shares your Initiative count, but it takes its turn immediately after yours. It obeys your verbal commands (no action required by you). If you don't issue any, it takes the Dodge action and uses its movement to avoid danger. Using a Higher-Level Spell Slot. Use the spell slot's level for the spell's level in the stat block. Fiendish Spirit Large Fiend, Neutral Armor Class: 12 + the spell's level Hit Points: HP 50 (Demon only) or 40 (Devil only) or 60 (Yugoloth only) + 15 for each spell level above 6 Speed: 40 ft.; Climb 40 ft. (Demon only); Fly 60 ft. [...]",
            setOf(WARLOCK, WIZARD), concentration = true),
        SpellDef("sunbeam", "Sunbeam", 6, "Evocation", "Action", "Self", "V, S, M (a magnifying glass)", "1 minute",
            "You launch a sunbeam in a 5-foot-wide, 60-foot-long Line. Each creature in the Line makes a Constitution saving throw. On a failed save, a creature takes 6d8 Radiant damage and has the Blinded condition until the start of your next turn. On a successful save, it takes half as much damage only. Until the spell ends, you can take a Magic action to create a new Line of radiance. For the duration, a mote of brilliant radiance shines above you. It sheds Bright Light in a 30-foot radius and Dim Light for an additional 30 feet. This light is sunlight.",
            setOf(CLERIC, DRUID, SORCERER, WIZARD), concentration = true),
        SpellDef("tasha_s_bubbling_cauldron", "Tasha's Bubbling Cauldron", 6, "Conjuration", "Action", "5 feet", "V, S, M (a gilded ladle worth 500+ GP)", "10 minutes",
            "You conjure a claw-footed cauldron filled with bubbling liquid. The cauldron appears in an unoccupied space on the ground within 5 feet of you and lasts for the duration. The cauldron can't be moved and disappears when the spell ends, along with the bubbling liquid inside it. The liquid in the cauldron duplicates the properties of a Common or an Uncommon potion of your choice (such as a Potion of Healing ). As a Bonus Action, you or an ally can reach into the cauldron and withdraw one potion of that kind. The potion is contained in a vial that disappears when the potion is consumed. The cauldron can produce a number of these potions equal to your spellcasting ability modifier (minimum 1). When the last of these potions is withdrawn from the cauldron, the cauldron disappears, and the spell ends. Potions obtained from the cauldron that aren't consumed disappear when you cast this spell again.",
            setOf(WARLOCK, WIZARD)),
        SpellDef("transport_via_plants", "Transport via Plants", 6, "Conjuration", "Action", "10 feet", "V, S", "1 minute",
            "This spell creates a magical link between a Large or larger inanimate plant within range and another plant, at any distance, on the same plane of existence. You must have seen or touched the destination plant at least once before. For the duration, any creature can step into the target plant and exit from the destination plant by using 5 feet of movement.",
            setOf(DRUID)),
        SpellDef("true_seeing", "True Seeing", 6, "Divination", "Action", "Touch", "V, S, M (mushroom powder worth 25+ GP, which the spell consumes)", "1 hour",
            "For the duration, the willing creature you touch has Truesight with a range of 120 feet.",
            setOf(BARD, CLERIC, SORCERER, WARLOCK, WIZARD)),
        SpellDef("wall_of_ice", "Wall of Ice", 6, "Evocation", "Action", "120 feet", "V, S, M (a piece of quartz)", "10 minutes",
            "You create a wall of ice on a solid surface within range. You can form it into a hemispherical dome or a globe with a radius of up to 10 feet, or you can shape a flat surface made up of ten 10-foot-square panels. Each panel must be contiguous with another panel. In any form, the wall is 1 foot thick and lasts for the duration. If the wall cuts through a creature's space when it appears, the creature is pushed to one side of the wall (you choose which side) and makes a Dexterity saving throw, taking 10d6 Cold damage on a failed save or half as much damage on a successful one. The wall is an object that can be damaged and thus breached. It has AC 12 and 30 Hit Points per 10-foot section, and it has Immunity to Cold, Poison, and Psychic damage and Vulnerability to Fire damage. Reducing a 10-foot section of wall to 0 Hit Points destroys it and leaves behind a sheet of frigid air in the space the wall occupied. A creature moving through the sheet of frigid air for the first time on a turn makes a Constitution saving throw, taking 5d6 Cold damage on a failed save or half as much damage on a successful one. Using a Higher-Level Spell Slot. [...]",
            setOf(WIZARD), concentration = true),
        SpellDef("wall_of_thorns", "Wall of Thorns", 6, "Conjuration", "Action", "120 feet", "V, S, M (a handful of thorns)", "10 minutes",
            "You create a wall of tangled brush bristling with needle-sharp thorns. The wall appears within range on a solid surface and lasts for the duration. You choose to make the wall up to 60 feet long, 10 feet high, and 5 feet thick or a circle that has a 20-foot diameter and is up to 20 feet high and 5 feet thick. The wall blocks line of sight. When the wall appears, each creature in its area makes a Dexterity saving throw, taking 7d8 Piercing damage on a failed save or half as much damage on a successful one. A creature can move through the wall, albeit slowly and painfully. For every 1 foot a creature moves through the wall, it must spend 4 feet of movement. Furthermore, the first time a creature enters a space in the wall on a turn or ends its turn there, the creature makes a Dexterity saving throw, taking 7d8 Slashing damage on a failed save or half as much damage on a successful one. A creature makes this save only once per turn. Using a Higher-Level Spell Slot. Both types of damage increase by 1d8 for each spell slot level above 6.",
            setOf(DRUID), concentration = true),
        SpellDef("wind_walk", "Wind Walk", 6, "Transmutation", "1 minute", "30 feet", "V, S, M (a candle)", "8 hours",
            "You and up to ten willing creatures of your choice within range assume gaseous forms for the duration, appearing as wisps of cloud. While in this cloud form, a target has a Fly Speed of 300 feet and can hover; it has Immunity to the Prone condition; and it has Resistance to Bludgeoning, Piercing, and Slashing damage. The only actions a target can take in this form are the Dash action or a Magic action to begin reverting to its normal form. Reverting takes 1 minute, during which the target has the Stunned condition. Until the spell ends, the target can revert to cloud form, which also requires a Magic action followed by a 1-minute transformation. If a target is in cloud form and flying when the effect ends, the target descends 60 feet per round for 1 minute until it lands, which it does safely. If it can't land after 1 minute, it falls the remaining distance.",
            setOf(DRUID)),
        SpellDef("word_of_recall", "Word of Recall", 6, "Conjuration", "Action", "5 feet", "V", "Instantaneous",
            "You and up to five willing creatures within 5 feet of you instantly teleport to a previously designated sanctuary. You and any creatures that teleport with you appear in the nearest unoccupied space to the spot you designated when you prepared your sanctuary (see below). If you cast this spell without first preparing a sanctuary, the spell has no effect. You must designate a location, such as a temple, as a sanctuary by casting this spell there.",
            setOf(CLERIC)),

        // ------------------------------------------------- Imported: Level 7
        SpellDef("conjure_celestial", "Conjure Celestial", 7, "Conjuration", "Action", "90 feet", "V, S", "10 minutes",
            "You conjure a spirit from the Upper Planes, which manifests as a pillar of light in a 10-foot-radius, 40-foot-high Cylinder centered on a point within range. For each creature you can see in the Cylinder, choose which of these lights shines on it: Healing Light. The target regains Hit Points equal to 4d12 plus your spellcasting ability modifier. Searing Light. The target makes a Dexterity saving throw, taking 6d12 Radiant damage on a failed save or half as much damage on a successful one. Until the spell ends, Bright Light fills the Cylinder, and when you move on your turn, you can also move the Cylinder up to 30 feet. Whenever the Cylinder moves into the space of a creature you can see and whenever a creature you can see enters the Cylinder or ends its turn there, you can bathe it in one of the lights. A creature can be affected by this spell only once per turn. Using a Higher-Level Spell Slot. The healing and damage increase by 1d12 for each spell slot level above 7.",
            setOf(CLERIC), concentration = true),
        SpellDef("delayed_blast_fireball", "Delayed Blast Fireball", 7, "Evocation", "Action", "150 feet", "V, S, M (a ball of bat guano and sulfur)", "1 minute",
            "A beam of yellow light flashes from you, then condenses at a chosen point within range as a glowing bead for the duration. When the spell ends, the bead explodes, and each creature in a 20-foot-radius Sphere centered on that point makes a Dexterity saving throw. A creature takes Fire damage equal to the total accumulated damage on a failed save or half as much damage on a successful one. The spell's base damage is 12d6, and the damage increases by 1d6 whenever your turn ends and the spell hasn't ended. If a creature touches the glowing bead before the spell ends, that creature makes a Dexterity saving throw. On a failed save, the spell ends, causing the bead to explode. On a successful save, the creature can throw the bead up to 40 feet. If the thrown bead enters a creature's space or collides with a solid object, the spell ends, and the bead explodes. When the bead explodes, flammable objects in the explosion that aren't being worn or carried start burning. Using a Higher-Level Spell Slot. The base damage increases by 1d6 for each spell slot level above 7.",
            setOf(SORCERER, WIZARD), concentration = true),
        SpellDef("divine_word", "Divine Word", 7, "Evocation", "Bonus Action", "30 feet", "V", "Instantaneous",
            "You utter a word imbued with power from the Upper Planes. Each creature of your choice in range makes a Charisma saving throw. On a failed save, a target that has 50 Hit Points or fewer suffers an effect based on its current Hit Points, as shown in the Divine Word Effects table. Regardless of its Hit Points, a Celestial, an Elemental, a Fey, or a Fiend target that fails its save is forced back to its plane of origin (if it isn't there already) and can't return to the current plane for 24 hours by any means short of a Wish spell. Divine Word Effects Hit Points Effect 0-20 The target dies. 21-30 The target has the Blinded, Deafened, and Stunned conditions for 1 hour. 31-40 The target has the Blinded and Deafened conditions for 10 minutes. 41-50 The target has the Deafened condition for 1 minute.",
            setOf(CLERIC)),
        SpellDef("etherealness", "Etherealness", 7, "Conjuration", "Action", "Self", "V, S", "Up to 8 hours",
            "You step into the border regions of the Ethereal Plane, where it overlaps with your current plane. You remain in the Border Ethereal for the duration. During this time, you can move in any direction. If you move up or down, every foot of movement costs an extra foot. You can perceive the plane you left, which looks gray, and you can't see anything there more than 60 feet away. While on the Ethereal Plane, you can affect and be affected only by creatures, objects, and effects on that plane. Creatures that aren't on the Ethereal Plane can't perceive or interact with you unless a feature gives them the ability to do so. When the spell ends, you return to the plane you left in the spot that corresponds to your space in the Border Ethereal. If you appear in an occupied space, you are shunted to the nearest unoccupied space and take Force damage equal to twice the number of feet you are moved. This spell ends instantly if you cast it while you are on the Ethereal Plane or a plane that doesn't border it, such as one of the Outer Planes. Using a Higher-Level Spell Slot. You can target up to three willing creatures (including yourself) for each spell slot level above 7. [...]",
            setOf(BARD, CLERIC, SORCERER, WARLOCK, WIZARD)),
        SpellDef("finger_of_death", "Finger of Death", 7, "Necromancy", "Action", "60 feet", "V, S", "Instantaneous",
            "You unleash negative energy toward a creature you can see within range. The target makes a Constitution saving throw, taking 7d8 + 30 Necrotic damage on a failed save or half as much damage on a successful one. A Humanoid killed by this spell rises at the start of your next turn as a Zombie (see appendix B) that follows your verbal orders.",
            setOf(SORCERER, WARLOCK, WIZARD)),
        SpellDef("fire_storm", "Fire Storm", 7, "Evocation", "Action", "150 feet", "V, S", "Instantaneous",
            "A storm of fire appears within range. The area of the storm consists of up to ten 10-foot Cubes, which you arrange as you like. Each Cube must be contiguous with at least one other Cube. Each creature in the area makes a Dexterity saving throw, taking 7d10 Fire damage on a failed save or half as much damage on a successful one. Flammable objects in the area that aren't being worn or carried start burning.",
            setOf(CLERIC, DRUID, SORCERER)),
        SpellDef("forcecage", "Forcecage", 7, "Evocation", "Action", "100 feet", "V, S, M (ruby dust worth 1,500+ GP, which the spell consumes)", "1 hour",
            "An immobile, Invisible, Cube-shaped prison composed of magical force springs into existence around an area you choose within range. The prison can be a cage or a solid box, as you choose. A prison in the shape of a cage can be up to 20 feet on a side and is made from 1/2-inch diameter bars spaced 1/2 inch apart. A prison in the shape of a box can be up to 10 feet on a side, creating a solid barrier that prevents any matter from passing through it and blocking any spells cast into or out from the area. When you cast the spell, any creature that is completely inside the cage's area is trapped. Creatures only partially within the area, or those too large to fit inside it, are pushed away from the center of the area until they are completely outside it. A creature inside the cage can't leave it by nonmagical means. If the creature tries to use teleportation or interplanar travel to leave, it must first make a Charisma saving throw. On a successful save, the creature can use that magic to exit the cage. On a failed save, the creature doesn't exit the cage and wastes the spell or effect. The cage also extends into the Ethereal Plane, blocking ethereal travel. [...]",
            setOf(BARD, WARLOCK, WIZARD), concentration = true),
        SpellDef("mirage_arcane", "Mirage Arcane", 7, "Illusion", "10 minutes", "Sight", "V, S", "10 days",
            "You make terrain in an area up to 1 mile square look, sound, smell, and even feel like some other sort of terrain. Open fields or a road could be made to resemble a swamp, hill, crevasse, or some other rough or impassable terrain. A pond can be made to seem like a grassy meadow, a precipice like a gentle slope, or a rock-strewn gully like a wide and smooth road. Similarly, you can alter the appearance of structures or add them where none are present. The spell doesn't disguise, conceal, or add creatures. The illusion includes audible, visual, tactile, and olfactory elements, so it can turn clear ground into Difficult Terrain (or vice versa) or otherwise impede movement through the area. Any piece of the illusory terrain (such as a rock or stick) that is removed from the spell's area disappears immediately. Creatures with Truesight can see through the illusion to the terrain's true form; however, all other elements of the illusion remain, so while the creature is aware of the illusion's presence, the creature can still physically interact with the illusion.",
            setOf(BARD, DRUID, WIZARD)),
        SpellDef("mordenkainen_s_magnificent_mansion", "Mordenkainen's Magnificent Mansion", 7, "Conjuration", "1 minute", "300 feet", "V, S, M (a miniature door worth 15+ GP)", "24 hours",
            "You conjure a shimmering door in range that lasts for the duration. The door leads to an extradimensional dwelling and is 5 feet wide and 10 feet tall. You and any creature you designate when you cast the spell can enter the extradimensional dwelling as long as the door remains open. You can open or close it (no action required) if you are within 30 feet of it. While closed, the door is imperceptible. Beyond the door is a magnificent foyer with numerous chambers beyond. The dwelling's atmosphere is clean, fresh, and warm. You can create any floor plan you like for the dwelling, but it can't exceed 50 contiguous 10-foot Cubes. The place is furnished and decorated as you choose. It contains sufficient food to serve a nine-course banquet for up to 100 people. Furnishings and other objects created by this spell dissipate into smoke if removed from it. A staff of 100 near-transparent servants attends all who enter. You determine the appearance of these servants and their attire. They are invulnerable and obey your commands. Each servant can perform tasks that a human could perform, but they can't attack or take any action that would directly harm another creature. [...]",
            setOf(BARD, WIZARD)),
        SpellDef("mordenkainen_s_sword", "Mordenkainen's Sword", 7, "Evocation", "Action", "90 feet", "V, S, M (a miniature sword worth 250+ GP)", "1 minute",
            "You create a spectral sword that hovers within range. It lasts for the duration. When the sword appears, you make a melee spell attack against a target within 5 feet of the sword. On a hit, the target takes Force damage equal to 4d12 plus your spellcasting ability modifier. On your later turns, you can take a Bonus Action to move the sword up to 30 feet to a spot you can see and repeat the attack against the same target or a different one.",
            setOf(BARD, WIZARD), concentration = true),
        SpellDef("plane_shift", "Plane Shift", 7, "Conjuration", "Action", "Touch", "V, S, M (a forked, metal rod worth 250+ GP and attuned to a plane of existence)", "Instantaneous",
            "You and up to eight willing creatures who link hands in a circle are transported to a different plane of existence. You can specify a target destination in general terms, such as the City of Brass on the Elemental Plane of Fire or the palace of Dispater on the second level of the Nine Hells, and you appear in or near that destination, as determined by the DM. Alternatively, if you know the sigil sequence of a teleportation circle on another plane of existence, this spell can take you to that circle. If the teleportation circle is too small to hold all the creatures you transported, they appear in the closest unoccupied spaces next to the circle.",
            setOf(CLERIC, DRUID, SORCERER, WARLOCK, WIZARD)),
        SpellDef("power_word_fortify", "Power Word Fortify", 7, "Enchantment", "Action", "60 foot", "V", "Instantaneous",
            "You fortify up to six creatures you can see within range. The spell bestows 120 Temporary Hit Points, which you divide among the spell's recipients.",
            setOf(BARD, CLERIC)),
        SpellDef("prismatic_spray", "Prismatic Spray", 7, "Evocation", "Action", "Self", "V, S", "Instantaneous",
            "Eight rays of light flash from you in a 60-foot Cone. Each creature in the Cone makes a Dexterity saving throw. For each target, roll 1d8 to determine which color ray affects it, consulting the Prismatic Rays table. Prismatic Rays 1d8 Ray 1 Red. Failed Save : 12d6 Fire damage. Successful Save : Half as much damage. 2 Orange. Failed Save : 12d6 Acid damage. Successful Save : Half as much damage. 3 Yellow. Failed Save : 12d6 Lightning damage. Successful Save : Half as much damage. 4 Green. Failed Save : 12d6 Poison damage. Successful Save : Half as much damage. 5 Blue. Failed Save : 12d6 Cold damage. Successful Save : Half as much damage. 6 Indigo. Failed Save : The target has the Restrained condition and makes a Constitution saving throw at the end of each of its turns. If it successfully saves three times, the condition ends. If it fails three times, it has the Petrified condition until it is freed by an effect like the Greater Restoration spell. The successes and failures needn't be consecutive; keep track of both until the target collects three of a kind. 7 Violet. Failed Save : The target has the Blinded condition and makes a Wisdom saving throw at the start of your next turn. [...]",
            setOf(BARD, SORCERER, WIZARD)),
        SpellDef("project_image", "Project Image", 7, "Illusion", "Action", "500 miles", "V, S, M (a statuette of yourself worth 5+ GP)", "1 day",
            "You create an illusory copy of yourself that lasts for the duration. The copy can appear at any location within range that you have seen before, regardless of intervening obstacles. The illusion looks and sounds like you, but it is intangible. If the illusion takes any damage, it disappears, and the spell ends. You can see through the illusion's eyes and hear through its ears as if you were in its space. As a Magic action, you can move it up to 60 feet and make it gesture, speak, and behave in whatever way you choose. It mimics your mannerisms perfectly. Physical interaction with the image reveals it to be illusory, since things can pass through it. A creature that takes the Study action to examine the image can determine that it is an illusion with a successful Intelligence (Investigation) check against your spell save DC. If a creature discerns the illusion for what it is, the creature can see through the image, and any noise it makes sounds hollow to the creature.",
            setOf(BARD, WIZARD), concentration = true),
        SpellDef("regenerate", "Regenerate", 7, "Transmutation", "1 minute", "Touch", "V, S, M (a prayer wheel)", "1 hour",
            "A creature you touch regains 4d8 + 15 Hit Points. For the duration, the target regains 1 Hit Point at the start of each of its turns, and any severed body parts regrow after 2 minutes.",
            setOf(BARD, CLERIC, DRUID)),
        SpellDef("resurrection", "Resurrection", 7, "Necromancy", "1 hour", "Touch", "V, S, M (a diamond worth 1,000+ GP, which the spell consumes)", "Instantaneous",
            "With a touch, you revive a dead creature that has been dead for no more than a century, didn't die of old age, and wasn't Undead when it died. The creature returns to life with all its Hit Points. This spell also neutralizes any poisons that affected the creature at the time of death. This spell closes all mortal wounds and restores any missing body parts. Coming back from the dead is an ordeal. The target takes a −4 penalty to D20 Tests. Every time the target finishes a Long Rest, the penalty is reduced by 1 until it becomes 0. Casting this spell to revive a creature that has been dead for 365 days or longer taxes you. Until you finish a Long Rest, you can't cast spells again, and you have Disadvantage on D20 Tests.",
            setOf(BARD, CLERIC)),
        SpellDef("reverse_gravity", "Reverse Gravity", 7, "Transmutation", "Action", "100 feet", "V, S, M (a lodestone and iron filings)", "1 minute",
            "This spell reverses gravity in a 50-foot-radius, 100-foot high Cylinder centered on a point within range. All creatures and objects in that area that aren't anchored to the ground fall upward and reach the top of the Cylinder. A creature can make a Dexterity saving throw to grab a fixed object it can reach, thus avoiding the fall upward. If a ceiling or an anchored object is encountered in this upward fall, creatures and objects strike it just as they would during a downward fall. If an affected creature or object reaches the Cylinder's top without striking anything, it hovers there for the duration. When the spell ends, affected objects and creatures fall downward.",
            setOf(DRUID, SORCERER, WIZARD), concentration = true),
        SpellDef("sequester", "Sequester", 7, "Transmutation", "Action", "Touch", "V, S, M (gem dust worth 5,000+ GP, which the spell consumes)", "Until dispelled",
            "With a touch, you magically sequester an object or a willing creature. For the duration, the target has the Invisible condition and can't be targeted by Divination spells, detected by magic, or viewed remotely with magic. If the target is a creature, it enters a state of suspended animation; it has the Unconscious condition, doesn't age, and doesn't need food, water, or air. You can set a condition for the spell to end early. The condition can be anything you choose, but it must occur or be visible within 1 mile of the target. Examples include \"after 1,000 years\" or \"when the tarrasque awakens.\" This spell also ends if the target takes any damage.",
            setOf(WIZARD)),
        SpellDef("simbul_s_synostodweomer", "Simbul's Synostodweomer", 7, "Transmutation", "Action", "Touch", "V, S", "1 hour",
            "You imbue one creature you touch with magical healing energy for the duration. Whenever the target casts a spell using a spell slot, the target can immediately roll a number of unexpended Hit Point Dice equal to the spell slot's level and regain Hit Points equal to the roll's total plus your spellcasting ability modifier; those dice are then expended.",
            setOf(SORCERER, WIZARD), book = Sourcebook.HEROES_OF_FAERUN),
        SpellDef("simulacrum", "Simulacrum", 7, "Illusion", "12 hours", "Touch", "V, S, M (powdered ruby worth 1,500+ GP, which the spell consumes)", "Until dispelled",
            "You create a simulacrum of one Beast or Humanoid that is within 10 feet of you for the entire casting of the spell. You finish the casting by touching both the creature and a pile of ice or snow that is the same size as that creature, and the pile turns into the simulacrum, which is a creature. It uses the game statistics of the original creature at the time of casting, except it is a Construct, its Hit Point maximum is half as much, and it can't cast this spell. The simulacrum is Friendly to you and creatures you designate. It obeys your commands and acts on your turn in combat. The simulacrum can't gain levels, and it can't take Short or Long Rests. If the simulacrum takes damage, the only way to restore its Hit Points is to repair it as you take a Long Rest, during which you expend components worth 100 GP per Hit Point restored. The simulacrum must stay within 5 feet of you for the repair. The simulacrum lasts until it drops to 0 Hit Points, at which point it reverts to snow and melts away. If you cast this spell again, any simulacrum you created with this spell is instantly destroyed.",
            setOf(WIZARD)),
        SpellDef("symbol", "Symbol", 7, "Abjuration", "1 minute", "Touch", "V, S, M (powdered diamond worth 1,000+ GP, which the spell consumes)", "Until dispelled or triggered",
            "You inscribe a harmful glyph either on a surface (such as a section of floor or wall) or within an object that can be closed (such as a book or chest). The glyph can cover an area no larger than 10 feet in diameter. If you choose an object, it must remain in place; if it is moved more than 10 feet from where you cast this spell, the glyph is broken, and the spell ends without being triggered. The glyph is nearly imperceptible and requires a successful Wisdom (Perception) check against your spell save DC to notice. When you inscribe the glyph, you set its trigger and choose which effect the symbol bears: Death, Discord, Fear, Pain, Sleep, or Stunning. Each one is explained below. Set the Trigger. You decide what triggers the glyph when you cast the spell. For glyphs inscribed on a surface, common triggers include touching or stepping on the glyph, removing another object covering it, or approaching within a certain distance of it. For glyphs inscribed within an object, common triggers include opening that object or seeing the glyph. You can refine the trigger so that only creatures of certain types activate it (for example, the glyph could be set to affect Aberrations). [...]",
            setOf(BARD, CLERIC, DRUID, WIZARD)),
        SpellDef("teleport", "Teleport", 7, "Conjuration", "Action", "10 feet", "V", "Instantaneous",
            "This spell instantly transports you and up to eight willing creatures that you can see within range, or a single object that you can see within range, to a destination you select. If you target an object, it must be Large or smaller, and it can't be held or carried by an unwilling creature. The destination you choose must be known to you, and it must be on the same plane of existence as you. Your familiarity with the destination determines whether you arrive there successfully. The DM rolls 1d100 and consults the Teleportation Outcome table and the explanations after it. Teleportation Outcome Familiarity Mishap Similar Area Off Target On Target Permanent circle - - - 01-00 Linked object - - - 01-00 Very familiar 01-05 06-13 14-24 25-00 Seen casually 01-33 34-43 44-53 54-00 Viewed once or described 01-43 44-53 54-73 74-00 False destination 01-50 51-00 - - Familiarity. Here are the meanings of the terms in the table's Familiarity column: \"Permanent circle\" means a permanent teleportation circle whose sigil sequence you know. \"Linked object\" means you possess an object taken from the desired destination within the last six months, such as a book from a wizard's library. [...]",
            setOf(BARD, SORCERER, WIZARD)),
        SpellDef("void_star", "Void Star", 7, "Necromancy", "Action", "120 feet", "V, S, M (a fragment of a meteor)", "Instantaneous",
            "You conjure forth a fragment of a dark star and launch it at one creature that you can see within range. Make a ranged spell attack against the target. On a hit, the target takes 6d12 Necrotic damage. Hit or miss, the target takes 3d12 Necrotic damage at the end of its next turn, and you regain Hit Points equal to that damage. Using a Higher-Level Spell Slot. The damage (both initial and later) increases by 1d12 for each spell slot level above 7.",
            setOf(WARLOCK, WIZARD), book = Sourcebook.DDB_DROPS),

        // ------------------------------------------------- Imported: Level 8
        SpellDef("animal_shapes", "Animal Shapes", 8, "Transmutation", "Action", "30 Feet", "V, S", "24 hours",
            "Choose any number of willing creatures that you can see within range. Each target shape-shifts into a Large or smaller Beast of your choice that has a Challenge Rating of 4 or lower. You can choose a different form for each target. On later turns, you can take a Magic action to transform the targets again. A target's game statistics are replaced by the chosen Beast's statistics, but the target retains its creature type; Hit Points; Hit Point Dice; alignment; ability to communicate; and Intelligence, Wisdom, and Charisma scores. The target's actions are limited by the Beast form's anatomy, and it can't cast spells. The target's equipment melds into the new form, and the target can't use any of that equipment while in that form. The target gains a number of Temporary Hit Points equal to the Hit Points of the first form into which it shape-shifts. These Temporary Hit Points vanish if any remain when the spell ends. The transformation lasts for the duration or until the target ends it as a Bonus Action.",
            setOf(DRUID)),
        SpellDef("antimagic_field", "Antimagic Field", 8, "Abjuration", "Action", "Self", "V, S, M (iron filings)", "1 hour",
            "An aura of antimagic surrounds you in 10-foot Emanation. No one can cast spells, take Magic actions, or create other magical effects inside the aura, and those things can't target or otherwise affect anything inside it. Magical properties of magic items don't work inside the aura or on anything inside it. Areas of effect created by spells or other magic can't extend into the aura, and no one can teleport into or out of it or use planar travel there. Portals close temporarily while in the aura. Ongoing spells, except those cast by an Artifact or a deity, are suppressed in the area. While an effect is suppressed, it doesn't function, but the time it spends suppressed counts against its duration. Dispel Magic has no effect on the aura, and the auras created by different Antimagic Field spells don't nullify each other.",
            setOf(CLERIC, WIZARD), concentration = true),
        SpellDef("antipathy_sympathy", "Antipathy/Sympathy", 8, "Enchantment", "1 Hour", "60 Feet", "V, S, M (a mix of vinegar and honey)", "10 Days",
            "As you cast the spell, choose whether it creates antipathy or sympathy, and target one creature or object that is Huge or smaller. Then specify a kind of creature, such as red dragons, goblins, or vampires. A creature of the chosen kind makes a Wisdom saving throw when it comes within 120 feet of the target. Your choice of antipathy or sympathy determines what happens to a creature when it fails that save: Antipathy. The creature has the Frightened condition. The Frightened creature must use its movement on its turns to get as far away as possible from the target, moving by the safest route. Sympathy. The creature has the Charmed condition. The Charmed creature must use its movement on its turns to get as close as possible to the target, moving by the safest route. If the creature is within 5 feet of the target, the creature can't willingly move away. If the target damages the Charmed creature, that creature can make a Wisdom saving throw to end the effect, as described below. Ending the Effect. If the Frightened or Charmed creature ends its turn more than 120 feet away from the target, the creature makes a Wisdom saving throw. [...]",
            setOf(BARD, DRUID, WIZARD)),
        SpellDef("befuddlement", "Befuddlement", 8, "Enchantment", "Action", "150 feet", "V, S, M (a key ring with no keys)", "Instantaneous",
            "You blast the mind of a creature that you can see within range. The target makes an Intelligence saving throw. On a failed save, the target takes 10d12 Psychic damage and can't cast spells or take the Magic action. At the end of every 30 days, the target repeats the save, ending the effect on a success. The effect can also be ended by the Greater Restoration , Heal , or Wish spell. On a successful save, the target takes half as much damage only.",
            setOf(BARD, DRUID, WARLOCK, WIZARD)),
        SpellDef("clone", "Clone", 8, "Necromancy", "1 hour", "Touch", "V, S, M (a diamond worth 1,000+ GP, which the spell consumes, and a sealable vessel worth 2,000+ GP that is large enough to hold the creature being cloned)", "Instantaneous",
            "You touch a creature or at least 1 cubic inch of its flesh. An inert duplicate of that creature forms inside the vessel used in the spell's casting and finishes growing after 120 days; you choose whether the finished clone is the same age as the creature or younger. The clone remains inert and endures indefinitely while its vessel remains undisturbed. If the original creature dies after the clone finishes forming, the creature's soul transfers to the clone if the soul is free and willing to return. The clone is physically identical to the original and has the same personality, memories, and abilities, but none of the original's equipment. The creature's original remains, if any, become inert and can't be revived, since the creature's soul is elsewhere.",
            setOf(WIZARD)),
        SpellDef("control_weather", "Control Weather", 8, "Transmutation", "10 minutes", "Self", "V, S, M (burning incense)", "8 hours",
            "You take control of the weather within 5 miles of you for the duration. You must be outdoors to cast this spell, and it ends early if you go indoors. When you cast the spell, you change the current weather conditions, which are determined by the DM. You can change precipitation, temperature, and wind. It takes 1d4 × 10 minutes for the new conditions to take effect. Once they do so, you can change the conditions again. When the spell ends, the weather gradually returns to normal. When you change the weather conditions, find a current condition on the following tables and change its stage by one, up or down. When changing the wind, you can change its direction. Precipitation Stage Condition 1 Clear 2 Light clouds 3 Overcast or ground fog 4 Rain, hail, or snow 5 Torrential rain, driving hail, or blizzard Temperature Stage Condition 1 Heat wave 2 Hot 3 Warm 4 Cool 5 Cold 6 Freezing Wind Stage Condition 1 Calm 2 Moderate wind 3 Strong wind 4 Gale 5 Storm",
            setOf(CLERIC, DRUID, WIZARD), concentration = true),
        SpellDef("demiplane", "Demiplane", 8, "Conjuration", "Action", "60 feet", "S", "1 hour",
            "You create a shadowy Medium door on a flat solid surface that you can see within range. This door can be opened and closed, and it leads to a demiplane that is an empty room 30 feet in each dimension, made of wood or stone (your choice). When the spell ends, the door vanishes, and any objects inside the demiplane remain there. Any creatures inside also remain unless they opt to be shunted through the door as it vanishes, landing with the Prone condition in the unoccupied spaces closest to the door's former space. Each time you cast this spell, you can create a new demiplane or connect the shadowy door to a demiplane you created with a previous casting of this spell. Additionally, if you know the nature and contents of a demiplane created by a casting of this spell by another creature, you can connect the shadowy door to that demiplane instead.",
            setOf(SORCERER, WARLOCK, WIZARD)),
        SpellDef("dominate_monster", "Dominate Monster", 8, "Enchantment", "Action", "60 feet", "V, S", "1 hour",
            "One creature you can see within range must succeed on a Wisdom saving throw or have the Charmed condition for the duration. The target has Advantage on the save if you or your allies are fighting it. Whenever the target takes damage, it repeats the save, ending the spell on itself on a success. You have a telepathic link with the Charmed target while the two of you are on the same plane of existence. On your turn, you can use this link to issue commands to the target (no action required), such as \"Attack that creature,\" \"Move over there,\" or \"Fetch that object.\" The target does its best to obey on its turn. If it completes an order and doesn't receive further direction from you, it acts and moves as it likes, focusing on protecting itself. You can command the target to take a Reaction but must take your own Reaction to do so. Using a Higher-Level Spell Slot. Your Concentration can last longer with a level 9 spell slot (up to 8 hours).",
            setOf(BARD, SORCERER, WARLOCK, WIZARD), concentration = true),
        SpellDef("earthquake", "Earthquake", 8, "Transmutation", "Action", "500 feet", "V, S, M (a fractured rock)", "1 minute",
            "Choose a point on the ground that you can see within range. For the duration, an intense tremor rips through the ground in a 100-foot-radius circle centered on that point. The ground there is Difficult Terrain. When you cast this spell and at the end of each of your turns for the duration, each creature on the ground in the area makes a Dexterity saving throw. On a failed save, a creature has the Prone condition, and its Concentration is broken. You can also cause the effects below. Fissures. A total of 1d6 fissures open in the spell's area at the end of the turn you cast it. You choose the fissures' locations, which can't be under structures. Each fissure is 1d10 × 10 feet deep and 10 feet wide, and it extends from one edge of the spell's area to another edge. A creature in the same space as a fissure must succeed on a Dexterity saving throw or fall in. A creature that successfully saves moves with the fissure's edge as it opens. Structures. The tremor deals 50 Bludgeoning damage to any structure in contact with the ground in the area when you cast the spell and at the end of each of your turns until the spell ends. If a structure drops to 0 Hit Points, it collapses. [...]",
            setOf(CLERIC, DRUID, SORCERER), concentration = true),
        SpellDef("glibness", "Glibness", 8, "Enchantment", "Action", "Self", "V", "1 hour",
            "Until the spell ends, when you make a Charisma check, you can replace the number you roll with a 15. Additionally, no matter what you say, magic that would determine if you are telling the truth indicates that you are being truthful.",
            setOf(BARD, WARLOCK)),
        SpellDef("holy_aura", "Holy Aura", 8, "Abjuration", "Action", "Self", "V, S, M (a reliquary worth 1,000+ GP)", "1 minute",
            "For the duration, you emit an aura in a 30-foot Emanation. While in the aura, creatures of your choice have Advantage on all saving throws, and other creatures have Disadvantage on attack rolls against them. In addition, when a Fiend or an Undead hits an affected creature with a melee attack roll, the attacker must succeed on a Constitution saving throw or have the Blinded condition until the end of its next turn.",
            setOf(CLERIC), concentration = true),
        SpellDef("holy_star_of_mystra", "Holy Star of Mystra", 8, "Evocation", "Bonus Action", "Self", "V, S", "1 minute",
            "You create a glowing mote of energy that hovers above you for the duration. The mote sheds Bright Light in a 5-foot radius and Dim Light for an additional 5 feet. When you cast this spell and as a Bonus Action on later turns, you can unleash a shining bolt from the mote, targeting one creature within 120 feet of yourself. Make a ranged spell attack. On a hit, the target takes Force or Radiant damage (your choice) equal to 4d10 plus your spellcasting ability modifier. In addition, while the mote is present, you have Three-Quarters Cover, and if you succeed on a saving throw against a spell of level 7 or lower that targeted only you and didn't create an area of effect, you can take a Reaction to deflect that spell back at the spell's caster; the caster makes a saving throw against that spell using that caster's own spell save DC.",
            setOf(CLERIC, WIZARD), concentration = true, book = Sourcebook.HEROES_OF_FAERUN),
        SpellDef("incendiary_cloud", "Incendiary Cloud", 8, "Conjuration", "Action", "150 feet", "V, S", "1 minute",
            "A swirling cloud of embers and smoke fills a 20-foot-radius Sphere centered on a point within range. The cloud's area is Heavily Obscured. It lasts for the duration or until a strong wind (like that created by Gust of Wind ) disperses it. When the cloud appears, each creature in it makes a Dexterity saving throw, taking 10d8 Fire damage on a failed save or half as much damage on a successful one. A creature must also make this save when the Sphere moves into its space and when it enters the Sphere or ends its turn there. A creature makes this save only once per turn. The cloud moves 10 feet away from you in a direction you choose at the start of each of your turns.",
            setOf(DRUID, SORCERER, WIZARD), concentration = true),
        SpellDef("maze", "Maze", 8, "Conjuration", "Action", "60 feet", "V, S", "10 minutes",
            "You banish a creature that you can see within range into a labyrinthine demiplane. The target remains there for the duration or until it escapes the maze. The target can take a Study action to try to escape. When it does so, it makes a DC 20 Intelligence (Investigation) check. If it succeeds, it escapes, and the spell ends. When the spell ends, the target reappears in the space it left or, if that space is occupied, in the nearest unoccupied space.",
            setOf(WIZARD), concentration = true),
        SpellDef("mind_blank", "Mind Blank", 8, "Abjuration", "Action", "Touch", "V, S", "24 hours",
            "Until the spell ends, one willing creature you touch has Immunity to Psychic damage and the Charmed condition. The target is also unaffected by anything that would sense its emotions or alignment, read its thoughts, or magically detect its location, and no spell - not even Wish - can gather information about the target, observe it remotely, or control its mind.",
            setOf(BARD, WIZARD)),
        SpellDef("power_word_stun", "Power Word Stun", 8, "Enchantment", "Action", "60 feet", "V", "Instantaneous",
            "You overwhelm the mind of one creature you can see within range. If the target has 150 Hit Points or fewer, it has the Stunned condition. Otherwise, its Speed is 0 until the start of your next turn. The Stunned target makes a Constitution saving throw at the end of each of its turns, ending the condition on itself on a success.",
            setOf(BARD, SORCERER, WARLOCK, WIZARD)),
        SpellDef("sunburst", "Sunburst", 8, "Evocation", "Action", "150 feet", "V, S, M (a piece of sunstone)", "Instantaneous",
            "Brilliant sunlight flashes in a 60-foot-radius Sphere centered on a point you choose within range. Each creature in the Sphere makes a Constitution saving throw. On a failed save, a creature takes 12d6 Radiant damage and has the Blinded condition for 1 minute. On a successful save, it takes half as much damage only. A creature Blinded by this spell makes another Constitution saving throw at the end of each of its turns, ending the effect on itself on a success. This spell dispels Darkness in its area that was created by any spell.",
            setOf(CLERIC, DRUID, SORCERER, WIZARD)),
        SpellDef("telepathy", "Telepathy", 8, "Divination", "Action", "Unlimited", "V, S, M (a pair of linked silver rings)", "24 hours",
            "You create a telepathic link between yourself and a willing creature with which you are familiar. The creature can be anywhere on the same plane of existence as you. The spell ends if you or the target are no longer on the same plane. Until the spell ends, you and the target can instantly share words, images, sounds, and other sensory messages with each other through the link, and the target recognizes you as the creature it is communicating with. The spell enables a creature to understand the meaning of your words and any sensory messages you send to it.",
            setOf(WIZARD)),
        SpellDef("tsunami", "Tsunami", 8, "Conjuration", "1 minute", "1 mile", "V, S", "6 rounds",
            "A wall of water springs into existence at a point you choose within range. You can make the wall up to 300 feet long, 300 feet high, and 50 feet thick. The wall lasts for the duration. When the wall appears, each creature in its area makes a Strength saving throw, taking 6d10 Bludgeoning damage on a failed save or half as much damage on a successful one. At the start of each of your turns after the wall appears, the wall, along with any creatures in it, moves 50 feet away from you. Any Huge or smaller creature inside the wall or whose space the wall enters when it moves must succeed on a Strength saving throw or take 5d10 Bludgeoning damage. A creature can take this damage only once per round. At the end of the turn, the wall's height is reduced by 50 feet, and the damage the wall deals on later rounds is reduced by 1d10. When the wall reaches 0 feet in height, the spell ends. A creature caught in the wall can move by swimming. Because of the wave's force, though, the creature must succeed on a Strength (Athletics) check against your spell save DC to move at all. If it fails the check, it can't move. A creature that moves out of the wall falls to the ground.",
            setOf(DRUID), concentration = true),

        // ------------------------------------------------- Imported: Level 9
        SpellDef("astral_projection", "Astral Projection", 9, "Necromancy", "1 hour", "10 feet", "V, S, M (for each of the spell's targets, one jacinth worth 1,000+ GP and one silver bar worth 100+ GP, all of which the spell consumes)", "Until dispelled",
            "You and up to eight willing creatures within range project your astral bodies into the Astral Plane (the spell ends instantly if you are already on that plane). Each target's body is left behind in a state of suspended animation; it has the Unconscious condition, doesn't need food or air, and doesn't age. A target's astral form resembles its body in almost every way, replicating it's game statistics and possessions. The principal difference is the addition of a silvery cord that trails from between the shoulderblades of the astral form. The cord fades from view after 1 foot. If the cord is cut - which happens only when an effect states that it does so - the target's body and astral form both die. A target's astral form can travel through the Astral Plane. The moment an astral form leaves that plane, the target's body and possessions travel along the silver cord, causing the target to re-enter its body on the new plane. Any damage or other effects that apply to an astral form have no effect on the target's body and vice versa. If a target's body or astral form drops to 0 Hit Points, the spell ends for that target. [...]",
            setOf(CLERIC, WARLOCK, WIZARD)),
        SpellDef("blade_of_disaster", "Blade Of Disaster", 9, "Conjuration", "Bonus Action", "60 feet", "V, S", "1 minute",
            "You create a 3-foot-long blade-shaped planar rift that lasts for the duration. The rift appears within range in a space of your choice, and you can immediately make up to two melee spell attacks, each one against a creature or object within 5 feet of the rift. On a hit, the target takes 10d6 Force damage. This attack scores a Critical Hit if the number on the d20 is 18 or higher. As a Bonus Action on your later turns, you can move the rift up to 60 feet and repeat the two attacks against a creature or an object within 5 feet of it. You can direct the attacks at the same target or at different ones. The blade can harmlessly pass through any barrier, including ones created by spells like Wall of Force .",
            setOf(SORCERER, WARLOCK, WIZARD), concentration = true, book = Sourcebook.HEROES_OF_FAERUN),
        SpellDef("foresight", "Foresight", 9, "Divination", "1 minute", "Touch", "V, S, M (a hummingbird feather)", "8 hours",
            "You touch a willing creature and bestow a limited ability to see into the immediate future. For the duration, the target has Advantage on D20 Tests, and other creatures have Disadvantage on attack rolls against it. The spell ends early if you cast it again.",
            setOf(BARD, DRUID, WARLOCK, WIZARD)),
        SpellDef("gate", "Gate", 9, "Conjuration", "Action", "60 feet", "V, S, M(a diamond worth 5,000+ GP)", "1 minute",
            "You conjure a portal linking an unoccupied space you can see within range to a precise location on a different plane of existence. The portal is a circular opening, which you can make 5 to 20 feet in diameter. You can orient the portal in any direction you choose. The portal lasts for the duration, and the portal's destination is visible through it. The portal has a front and a back on each plane where it appears. Travel through the portal is possible only by moving through its front. Anything that does so is instantly transported to the other plane, appearing in the unoccupied space nearest to the portal. Deities and other planar rulers can prevent portals created by this spell from opening in their presence or anywhere within their domains. When you cast this spell, you can speak the name of a specific creature (a pseudonym, title, or nickname doesn't work). If that creature is on a plane other than the one you are on, the portal opens next to the named creature and transports it to the nearest unoccupied space on your side of the portal. You gain no special power over the creature, and it is free to act as the DM deems appropriate. It might leave, attack you, or help you.",
            setOf(CLERIC, SORCERER, WARLOCK, WIZARD), concentration = true),
        SpellDef("imprisonment", "Imprisonment", 9, "Abjuration", "1 minute", "30 feet", "V, S, M(a statuette of the target worth 5,000+ GP)", "Until dispelled",
            "You create a magical restraint to hold a creature that you can see within range. The target must make a Wisdom saving throw. On a successful save, the target is unaffected, and it is immune to this spell for the next 24 hours. On a failed save, the target is imprisoned. While imprisoned, the target doesn't need to breathe, eat, or drink, and it doesn't age. Divination spells can't locate or perceive the imprisoned target, and the target can't teleport. Until the spell ends, the target is also affected by one of the following effects of your choice: Burial. The target is entombed beneath the earth in a hollow globe of magical force that is just large enough to contain the target. Nothing can pass into or out of the globe. Chaining. Chains firmly rooted in the ground hold the target in place. The target has the Restrained condition and can't be moved by any means. Hedged Prison. The target is trapped in a demiplane that is warded against teleportation and planar travel. The demiplane is your choice of a labyrinth, a cage, a tower, or the like. Minimus Containment. The target becomes 1 inch tall and is trapped inside an indestructible gemstone or a similar object. [...]",
            setOf(WARLOCK, WIZARD)),
